      // Panels: only one shows at a time. Flex column + gap rather than paragraph margins,
      // so the `> *{margin:0}` reset below can't leave two rows touching.
      + ".stbook-setup-section{display:flex;flex-direction:column;gap:10px;line-height:1.5}"
      + ".stbook-setup-section > *{margin:0}"
      + ".stbook-setup-section[hidden]{display:none}"
      + ".stbook-setup-titlewrap{display:flex;align-items:baseline;gap:6px;min-width:0}"
      + ".stbook-setup-optional{flex:0 0 auto;padding:0 6px;border:1px solid var(--st-text-muted,#777);border-radius:var(--st-radius-sm,3px);color:var(--st-text-muted,#777);font-size:.68em;font-weight:700;text-transform:uppercase;letter-spacing:.04em}"
      + ".stbook-setup-optional[hidden]{display:none}"
      // Count of what the GM has supplied, on the rail entry itself: the panels are
      // collapsed behind the rail now, so without this "Poster maps" gives no sign
      // whether anything was put in it.
      + ".stbook-setup-badge{flex:0 0 auto;padding:0 6px;border-radius:9px;background:var(--st-green-text,#4a6b3a);color:#fff;font-size:.7em;font-weight:700;line-height:1.7}"
      + ".stbook-setup-badge:empty{display:none}"
      + ".stbook-setup-note{font-size:var(--st-fs-xs,.78em)}"
      // Muting the note needs FIVE classes. `.stonetop-themed .window-content :is(label, p,
      // h1…, .form-group > label)` pins body colour on every paragraph in a themed window at
      // (0,4,1) — `:is()` takes its heaviest argument — so the plain one-class rule above is
      // beaten and these notes came out the same ink as the copy they are meant to sit under.
      + ".stbook-setup-dialog .window-content .stbook-setup .stbook-setup-section .stbook-setup-note{color:var(--st-text-muted,#777)}"
      // The "you can stop here" offer. Deliberately NOT a .stbook-setup-note: the muting rule
      // above would drop it to the same small grey as the asides it sits among, and the one
      // thing a GM has to be able to see is that they are allowed to leave. A boxed callout,
      // dashed rather than solid so it reads as an aside from the fields it follows, and left
      // at body size and body ink. No margin: the panel is a flex column with a gap.
      + ".stbook-setup-runhint{padding:8px 11px;border-radius:6px;background:rgba(75,55,30,.07);border:1px dashed rgba(75,55,30,.4)}"
      // One card per book / poster map. The map cards put the file button and the
      // "or a path" field on ONE row: five stacked two-line fieldsets were the whole
      // reason the old maps step ran off the bottom of the screen.
      + ".stbook-fields{display:flex;flex-direction:column;gap:6px}"
      + ".stbook-field{display:flex;flex-direction:column;gap:3px;padding:6px 8px;border:1px solid rgba(75,55,30,.22);border-radius:6px;background:rgba(75,55,30,.06)}"
      + ".stbook-field-name{font-weight:600;line-height:1.25}"
      + ".stbook-field-hint{font-weight:400;color:var(--st-text-muted,#777);font-size:var(--st-fs-xs,.78em)}"
      + ".stbook-field-inputs{display:flex;gap:6px;align-items:center}"
      // The file button sizes itself to its own chrome; the path box takes whatever is
      // left rather than an even half, which is what kept clipping its placeholder.
      + ".stbook-field-inputs > input[type=file]{flex:0 1 auto;width:auto;min-width:0}"
      + ".stbook-field-inputs > input[type=text]{flex:1 1 0;min-width:0}"
      + ".stbook-field input{width:100%}"
      // The last page's recap. One row per thing this window can be given, wearing the same card
      // as the fields those things were typed into, so the page reads as a summary OF them rather
      // than as another form. The value is muted until there is something to say, which makes the
      // filled rows the only thing with colour on the page.
      + ".stbook-ready{display:flex;flex-direction:column;gap:6px}"
      + ".stbook-ready-row{display:flex;align-items:baseline;gap:8px;padding:6px 9px;border:1px solid rgba(75,55,30,.22);border-radius:6px;background:rgba(75,55,30,.06)}"
      + ".stbook-ready-name{flex:1 1 auto;min-width:0;font-weight:600}"
      + ".stbook-ready-value{flex:0 0 auto;color:var(--st-text-muted,#777)}"
      + ".stbook-ready-value.is-on{color:var(--st-green-text,#4a6b3a);font-weight:600}"
      + ".stbook-ready-none[hidden]{display:none}"
      // "What do you have?": the two ways a GM actually holds these maps, worn as one row of
      // cards, then one `.stbook-map-mode` block per answer with only the chosen one shown.
      // Modes are hidden, never removed, for exactly the reason the panels are: a file the GM
      // has already chosen cannot be put back into a rebuilt <input type=file>.
      + ".stbook-mapsrc{display:flex;flex-wrap:wrap;gap:8px}"
      + ".stbook-mapsrc label{flex:1 1 14em;display:flex;gap:7px;align-items:flex-start;padding:6px 9px;border:1px solid rgba(75,55,30,.22);border-radius:6px;background:rgba(75,55,30,.06);cursor:pointer}"
      + ".stbook-mapsrc input{flex:none;width:auto;margin:3px 0 0}"
      + ".stbook-map-mode{display:flex;flex-direction:column;gap:10px}"
      + ".stbook-map-mode[hidden]{display:none}"
      // One row per map in PDF mode: a thumbnail of the page it will take, the map's name, the
      // page number. The thumbnail is the point of the whole row - it turns "trust that page 3
      // is the World's End" into something the GM can see before a minute of work starts.
      // `border:0` because core paints a 1px black border on every img inside an application.
      + ".stbook-field--maprow{flex-direction:row;align-items:center;gap:9px}"
      + ".stbook-maprow-thumb{flex:0 0 auto;width:62px;height:48px;display:flex;align-items:center;justify-content:center;border:1px solid rgba(75,55,30,.24);border-radius:4px;background:rgba(75,55,30,.10);overflow:hidden}"
      + ".stbook-maprow-thumb img{max-width:100%;max-height:100%;display:block;border:0}"
      + ".stbook-maprow-body{flex:1 1 auto;min-width:0}"
      + ".stbook-field--maprow input{flex:0 0 auto;width:5em}"
      + ".stbook-mapspdf-status{min-height:1.2em}";
    document.head.appendChild(st);
  }
  const progress = (() => {
    let dlg = null;
    const state = { phase: "Working…", detail: "", frac: null };
    const paint = () => {
      const root = dlg?.element?.querySelector?.(".stbook-progress");
      if (!root) return;
      root.classList.toggle("is-indeterminate", state.frac == null);
      const set = (sel, txt) => { const el = root.querySelector(sel); if (el) el.textContent = txt; };
      set(".stbook-phase", state.phase);
      set(".stbook-detail", state.detail);
      const fill = root.querySelector(".stbook-fill");
      if (fill && state.frac != null) fill.style.width = Math.round(Math.max(0, Math.min(1, state.frac)) * 100) + "%";
    };
    return {
      async open(phase) {
        state.phase = phase ?? state.phase; state.frac = null; state.detail = "";
        if (dlg?.rendered) { paint(); return; }
        dlg = new foundry.applications.api.DialogV2({
          classes: DLG_CLASSES,
          window: { title: "Import Book Art" },
          position: { width: 460 },
          content: `<div class="stbook-progress is-indeterminate"><p class="stbook-phase">${esc(state.phase)}</p>`
            + `<div class="stbook-track"><div class="stbook-fill"></div></div><p class="stbook-detail"></p></div>`,
          buttons: [{ action: "hide", label: "Run in Background", callback: () => {} }],
        });
        await dlg.render({ force: true });
        paint();
      },
      phase(phase, detail = "") { state.phase = phase; state.detail = detail; state.frac = null; paint(); },
      step(frac, detail) { state.frac = frac; if (detail != null) state.detail = detail; paint(); },
      note(detail) { state.detail = detail; paint(); },
      async close() { try { await dlg?.close(); } catch (_) {} dlg = null; },
    };
  })();

  // Foundry's bundled pdf.js, loaded at most once. Hoisted above the setup dialog because
  // the dialog now needs it too: when the GM says they have the single all-maps PDF, each
  // map row previews the page it is about to take. Section 2 awaits the same promise, so
  // the engine is never fetched twice. A failure clears the cache rather than poisoning it.
  let pdfjsPromise = null;
  const loadPdfjs = () => (pdfjsPromise ??= (async () => {
    const m = await import(foundry.utils.getRoute("/scripts/pdfjs/build/pdf.mjs"));
    m.GlobalWorkerOptions.workerSrc = foundry.utils.getRoute("/scripts/pdfjs/build/pdf.worker.mjs");
    return m;
  })().catch((e) => { pdfjsPromise = null; throw e; }));

  // ---- 1. setup dialog -----------------------------------------------------
  // Everything the run needs from the GM, in ONE window worn as the same left-rail
  // "stepped sheet" as the Welcome guide: What this does / Your books / Poster maps /
  // Ready to import. It used to be two stacked screens — a very long intro, then an even longer
  // five-fieldset maps prompt after the PDFs had loaded — and both ran off the bottom of
  // the window. The rail switches panels client-side so the window keeps ONE height and
  // the panel column scrolls inside it.
  //
  // Panels are hidden, never removed. That is load-bearing rather than incidental: a
  // <input type=file> selection cannot be re-created from script, so a panel rebuilt on
  // every switch would silently drop the book the GM had already chosen.
  //
  // The rail sync below is a deliberate local copy of module/utils/guide-rail.js, not an
  // import. It is DOM cosmetics — a drifted copy highlights the wrong rail entry and can
  // write nothing wrong to the world — and this macro is meant to stay pasteable on its
  // own. Contrast the poster-map Scene builder in section 7b, which IS imported, because
  // there a drifted copy would match Scenes by different rules and duplicate them.
  //
  // Most monster + location art is in Book II; a few monsters (e.g. the Swyn) are only in
  // Book I. We show a file field for every book the manifest references and use whatever
  // the user supplies. Embedded <input type=file> fields open the OS picker on the user's
  // own click, so no user-gesture juggling is needed.
  //
  // A row's `book` is a small integer that names ONE of the PDFs a GM might own, and 3 is the
  // free GM playbook rather than a third rulebook — which is why every label below comes out of
  // this table instead of being assembled from the number. `roman` survives for the two that
  // really are numbered volumes; nothing outside this table may spell a book's name, or the
  // GM playbook shows up somewhere as "Book 3".
  const BOOKS = {
    1: { title: "Book I: Stonetop", label: "Book I", expected: "expectedPdfPagesBook1",
         note: "a few monsters drawn only here, like the Swyn" },
    2: { title: "Book II: The Wider World", label: "Book II", expected: "expectedPdfPages",
         note: "most of the monster & location art" },
    // Optional and small (12 pages, and free from the publisher). It is worth offering because
    // it is the best source in print for three pictures we already show: it prints the Village,
    // Vicinity and World's End maps at a true 300 dpi, where Book I embeds the village map at
    // 478x272 and Book II the other two at ~700px. It also carries the two flowcharts, which
    // are in no other PDF at all.
    // `editions` overrides the "which file do you mean" line under the field. Only this one needs
    // it: the playbook is the only book we can read either way round (see pdfLayout), and its
    // 1-up download is the one the publisher's page hands you first, so a note naming only the
    // spreads edition would send a GM looking for a file they have no reason to have.
    // `oneUp` says this book may also be handed to us one printed page per sheet. Only the
    // playbook can be: every one of its rows RENDERS a region, so a sheet stitched back together
    // out of two pages serves it exactly. The rulebooks LIFT their illustrations out of the page
    // by size and placement, which a re-paginated file would have to be re-measured against
    // wholesale — so a 1-up rulebook is refused below rather than quietly mis-extracted.
    // `panel` moves this book's file field off "Your books" onto a rail entry of its own. It
    // earns one because it is a different KIND of thing to supply: free rather than bought, and
    // wanted for five specific pictures rather than for the bulk of the art. Sat as a third
    // field under the rulebooks it read as a book a GM ought to already have, and the two
    // paragraphs saying otherwise had to crowd in under fields they were not about.
    3: { title: "GM playbook", label: "the GM playbook", expected: "expectedPdfPagesGm",
         note: "sharper maps, plus the core loop & flow of play", oneUp: true, panel: "playbook",
         editions: "either download: the 12-page &quot;spreads&quot; one or the 1-up booklet" },
  };
  const roman = (b) => (b === 1 ? "I" : b === 2 ? "II" : String(b));
  const bookTitle = (b) => BOOKS[b]?.title ?? `Book ${roman(b)}`;
  // `bookLabel` is the mid-sentence form ("...and the GM playbook"), `bookLabelCap` the one that
  // starts a sentence. Two forms rather than one because "the GM playbook" carries an article that
  // "Book I" does not, so no single string reads correctly in both places — and the messages below
  // are the first thing a GM sees when a file will not open.
  const bookLabel = (b) => BOOKS[b]?.label ?? `Book ${roman(b)}`;
  const bookLabelCap = (b) => { const s = bookLabel(b); return s.charAt(0).toUpperCase() + s.slice(1); };
  const bookExpected = (b) => (BOOKS[b]?.expected ? MANIFEST.meta[BOOKS[b].expected] ?? null : null);
  const bookNote = (b) => BOOKS[b]?.note ?? "";
  // Books the manifest references, in book order (Book I first, then Book II, ...).
  const booksUsed = [...new Set(MANIFEST.rows.map((r) => r.book ?? 2))].sort((a, b) => a - b);
  // Which books a rail panel asks for. Read off the BOOKS table rather than listed here, so a
  // book moved between panels moves by editing the one entry that names it — and the fields, the
  // rail entry, the badge and what `collectBooks` reads all follow from that single answer.
  const booksOn = (key) => booksUsed.filter((b) => (BOOKS[b]?.panel ?? "books") === key);
  const bookFieldsFor = (key) => `<div class="stbook-fields">` + booksOn(key).map((b) => {
    const exp = bookExpected(b);
    return `<div class="stbook-field">`
      + `<div class="stbook-field-name">${esc(bookTitle(b))}`
      + (bookNote(b) ? ` <span class="stbook-field-hint">${esc(bookNote(b))}</span>` : "") + `</div>`
      + `<input type="file" name="book-file-${b}" accept="application/pdf,.pdf">`
      + (BOOKS[b]?.editions ? `<p class="stbook-setup-note">${BOOKS[b].editions}</p>`
        : exp ? `<p class="stbook-setup-note">the ${exp}-page &quot;spreads&quot; edition</p>` : "")
      + `</div>`;
  }).join("") + `</div>`;
  // The playbook's page only exists while a book actually asks for it. A manifest with no
  // book-3 rows would otherwise open a rail entry onto an empty panel.
  const playbookBooks = booksOn("playbook");
  const offerPlaybook = playbookBooks.length > 0;

  // The five poster maps are not embedded in the books at usable quality, so they cannot
  // be regenerated the way the illustrations are. Instead the GM may point us at map
  // images they own (exports, scans, the free Setting Overview handout). Each supplied map
  // becomes a navigation Scene configured like the private project's seeded scenes, and
  // the Stonetop village map gets its lettered places-of-interest pins placed automatically.
  //
  // A GM holds those maps one of two ways, and which one is not something we can detect: the
  // five separate 11x14 images, or the single "All maps" PDF that ships beside them, one map
  // per page. So the panel asks, and carries a block for each answer. The PDF answer is not a
  // convenience wrapper around the other one - there are no image files to hand us at all in
  // that case, so without it those GMs simply have no way to get their Scenes.
  const offerMaps = CONFIG.IMPORT_MAPS && !CONFIG.DRY_RUN && Array.isArray(MANIFEST.maps) && MANIFEST.maps.length > 0;
  const mapImageFields = !offerMaps ? "" : `<div class="stbook-fields">` + MANIFEST.maps.map((m, i) =>
    `<div class="stbook-field">`
    + `<div class="stbook-field-name">${esc(m.name)} <span class="stbook-field-hint">${esc(m.hint)}</span></div>`
    + `<div class="stbook-field-inputs">`
    + `<input type="file" name="map-file-${i}" accept="image/*">`
    + `<input type="text" name="map-path-${i}" placeholder="or a path in your data">`
    + `</div></div>`).join("") + `</div>`;

  // The all-maps PDF: one file field, then a row per map saying which page it takes. The page
  // numbers default to the order the maps are published in, which is the order every copy of
  // that PDF has been in - but they are editable, and each row previews its page as soon as
  // the file is chosen, so a GM whose PDF differs can see that and fix it rather than
  // discovering it afterwards in the scene nav bar. Clearing a number skips that map.
  const mapPdfFields = !offerMaps ? "" : `<div class="stbook-field">`
    + `<div class="stbook-field-name">Your all-maps PDF <span class="stbook-field-hint">one map per page</span></div>`
    + `<input type="file" name="maps-pdf" accept="application/pdf,.pdf">`
    + `<p class="stbook-setup-note stbook-mapspdf-status">Usually named <code>All maps - 11 x 14.pdf</code>.</p>`
    + `</div>`
    + `<div class="stbook-fields">` + MANIFEST.maps.map((m, i) =>
      `<div class="stbook-field stbook-field--maprow">`
      + `<span class="stbook-maprow-thumb"><img data-thumb="${i}" alt="" hidden></span>`
      + `<span class="stbook-maprow-body"><span class="stbook-field-name">${esc(m.name)}</span></span>`
      + `<span class="stbook-field-hint">page</span>`
      + `<input type="number" name="map-page-${i}" min="1" step="1" value="${i + 1}" aria-label="${esc(m.name)} page number">`
      + `</div>`).join("") + `</div>`
    + `<p class="stbook-setup-note">Each row shows the page it will use. Change a number if your PDF runs in a different order, or clear one to skip that map.</p>`;

  // Rail entries, in order. `badge` names the counter painted on the entry (see paintBadges);
  // `optional` tags the banner, because a GM who supplies no map still gets a complete import.
  //
  // `runLabel` gives the page an Import button of its OWN, which imports what that page holds and
  // nothing else. Every page that takes files gets one, because the three of them are genuinely
  // separate errands: a GM who came back only for their poster maps, or only to add the playbook
  // they have just downloaded, should not have to walk a rail of pages they mean to leave empty
  // to reach the button at the end. The last page's "Import Art" still does the lot.
  const SETUP_SECTIONS = [
    { key: "overview", title: "What this does", icon: "fa-circle-info" },
    { key: "books", title: "Your rulebooks", icon: "fa-book", badge: "books", runLabel: "Import these books" },
    ...(offerPlaybook ? [{ key: "playbook", title: bookTitle(playbookBooks[0]), icon: "fa-diagram-project", badge: "playbook", optional: true, runLabel: "Import the playbook" }] : []),
    ...(offerMaps ? [{ key: "maps", title: "Poster maps", icon: "fa-map", badge: "maps", optional: true, runLabel: "Import these maps" }] : []),
    { key: "ready", title: "Ready to import", icon: "fa-circle-check" },
  ];
  // What the last page recaps: every book this manifest asks for, then the maps if they are on
  // offer. Built off `booksUsed` rather than off the rail, because the recap is about the things
  // supplied and not the pages they were supplied on — a book moved to another panel keeps its
  // row here, and a manifest with no playbook rows never grows one.
  const READY_ROWS = [
    ...booksUsed.map((b) => ({ label: bookTitle(b), book: b })),
    ...(offerMaps ? [{ label: "Poster maps", key: "maps" }] : []),
  ];
  const sectionOf = (key) => SETUP_SECTIONS.find((s) => s.key === key);
  // The page's own offer, said on the page as well as shown in the footer. A button that appears
  // on one panel and not another reads as furniture; the whole value of it is knowing you may
  // stop, so the page says so in words, names its own button, and says what the alternative is.
  const runHint = (key) => {
    const s = sectionOf(key);
    return !s?.runLabel ? "" : `<p class="stbook-setup-runhint">`
      + `<strong>You can stop here.</strong> <em>${esc(s.runLabel)}</em>, at the bottom of this page, imports just what you filled in above and closes. Nothing else you have already imported is touched, and you can come back for the rest another time. `
      + `Or leave it and carry on down the rail: <strong>Import Art</strong> on the last page runs everything you have given us in one pass.</p>`;
  };
  const panel = (key, body) => `<section class="stbook-setup-section" data-tab="${key}"`
    + (key === SETUP_SECTIONS[0].key ? "" : " hidden") + `>${body}</section>`;
  const setupHtml = `<div class="stbook-setup"><div class="stonetop-guide-split">`
    + `<nav class="stonetop-guide-toc" aria-label="Import Book Art steps"><ol class="stonetop-guide-toc-list">`
    + SETUP_SECTIONS.map((s, i) => `<li class="stonetop-guide-toc-item${i === 0 ? " is-active" : ""}">`
      + `<button type="button" class="stonetop-guide-toc-btn stbook-setup-tab" data-tab="${s.key}"${i === 0 ? ' aria-current="true"' : ""}>`
      + `<i class="fas ${s.icon} stonetop-guide-toc-icon"></i>`
      + `<span class="stonetop-guide-toc-text">${esc(s.title)}</span>`
      + (s.badge ? `<span class="stbook-setup-badge" data-badge="${s.badge}"></span>` : "")
      + `</button></li>`).join("")
    + `</ol></nav>`
    + `<div class="stonetop-guide-main stbook-setup-main">`
    + `<div class="stonetop-guide-banner">`
    + `<i class="fas ${SETUP_SECTIONS[0].icon} stonetop-guide-banner-icon stbook-setup-banner-icon"></i>`
    + `<div class="stonetop-guide-banner-info"><div class="stbook-setup-titlewrap">`
    + `<span class="stonetop-guide-banner-title stbook-setup-title">${esc(SETUP_SECTIONS[0].title)}</span>`
    + `<span class="stbook-setup-optional" hidden>optional</span></div>`
    + `<div class="stonetop-guide-banner-sub">Import Book Art</div></div>`
    + `<div class="stonetop-guide-count stbook-setup-count">1 / ${SETUP_SECTIONS.length}</div>`
    + `</div>`

    + panel("overview",
      `<p>This rebuilds the copyrighted <strong>Stonetop</strong> illustrations from the PDFs <strong>you own</strong> and wires them into your Monsters and Stonetop compendia${offerMaps ? `, and turns the poster maps you own into ready-to-use Scenes` : ""}. Nothing is uploaded anywhere; everything is rebuilt locally on your own machine.</p>`
      + `<p>Work down the rail on the left: point <strong>Your rulebooks</strong> at the PDFs you own${offerPlaybook ? `, add the free <strong>GM playbook</strong> if you want the sharper maps and the two flowcharts it alone carries` : ""}${offerMaps ? `, and give <strong>Poster maps</strong> the maps you own` : ""}. Then hit <strong>Import Art</strong> on the last page to run the lot.</p>`
      + `<p><strong>Or do one page at a time.</strong> Each of those pages has an Import button of its own that runs just that page and closes, so if you only came to add your maps${offerPlaybook ? ` or the playbook` : ""}, you can fill in that one page and go. Each of them is a complete run on its own, and anything you have already imported is left exactly as it is, so coming back another time costs you nothing.</p>`
      + `<p>A full art import writes about ${imageCount} images and updates ${monsters.length} monster portraits plus location art, and takes 1-2 minutes${offerMaps ? `; maps on their own take seconds` : ""}. It shows progress as it goes, and is safe to re-run.</p>`
      + `<p class="stbook-safe"><strong>Your writing stays put.</strong> The macro only <em>adds</em> pictures to your monster and location journals; it never edits or removes any text you or your players have written, and a later system update won't either.</p>`
      + `<p class="stbook-setup-note">Requires the &quot;Upload New Files&quot; permission (GM or Assistant), which you have.</p>`)

    + panel("books",
      `<p><strong>Supply the books you have.</strong> Provide either or both of these PDFs; anything you skip is simply left out.</p>`
      + bookFieldsFor("books")
      + `<p class="stbook-setup-note">Between them these two hold nearly all of the art this imports: every monster portrait and every location illustration.${offerPlaybook ? ` The free <strong>GM playbook</strong> on the next page adds five more pictures on top.` : ""}</p>`
      + runHint("books"))

    // The playbook's own page. It is here to say the two things a GM cannot know from a file
    // field — that this one is free, and that it is worth the download even to someone who owns
    // both rulebooks — without those paragraphs sitting under the rulebooks they are not about.
    + (offerPlaybook ? panel("playbook",
      `<p>Optional, and <strong>free</strong>: this is the handout the publisher gives away, not a book you buy. Skip it and everything else still imports. But it is a 12-page download, and it is the best source in print for five of the pictures.</p>`
      + `<p><strong>What it adds.</strong> The Village, Vicinity and World's End maps at a true 300 dpi, where Book I embeds the village map at 478&times;272 and Book II the other two at around 700px across, so it is worth having even if you own both rulebooks. And the core-loop and flow-of-play diagrams, which are in no other PDF at all.</p>`
      + bookFieldsFor("playbook")
      + `<p class="stbook-setup-note">Which edition you handed us is read off the file itself, so both downloads import the same pictures.</p>`
      + `<p class="stbook-setup-note">Its maps go into the printed pages of the <strong>Setting Overview</strong> journal${offerMaps ? `, not into your map Scenes. Those come from whatever you give <strong>Poster maps</strong>` : ""}.</p>`
      + runHint("playbook")) : "")

    + (offerMaps ? panel("maps",
      `<p>Optional. Each poster map <strong>you own</strong> becomes a ready-to-use Scene; skip any you'd rather not have. The village map also gets its lettered places-of-interest pins placed for you.</p>`
      + `<p><strong>Which do you have?</strong> Both live in the <strong>Maps</strong> folder of your purchased copy of Stonetop.</p>`
      + `<div class="stbook-mapsrc">`
      + `<label><input type="radio" name="map-source" value="images" checked>`
      + `<span><strong>Separate map images</strong> <span class="stbook-field-hint">five files, named like <code>Map_1_-_Stonetop_-_11_x_14</code></span></span></label>`
      + `<label><input type="radio" name="map-source" value="pdf">`
      + `<span><strong>One PDF holding them all</strong> <span class="stbook-field-hint">usually <code>All maps - 11 x 14.pdf</code></span></span></label>`
      + `</div>`
      + `<div class="stbook-map-mode" data-mode="images">${mapImageFields}`
      + `<p class="stbook-setup-note">Leave a row empty to skip that map.</p></div>`
      + `<div class="stbook-map-mode" data-mode="pdf" hidden>${mapPdfFields}</div>`
      + `<p class="stbook-setup-note">This step is only about Scenes. The <strong>Setting Overview</strong> journal takes its printed, labelled maps out of the PDFs instead (best first, from the GM playbook if you gave us one and from Book II otherwise), so it fills those pages in when you import the books.</p>`
      + runHint("maps")) : "")

    // The finish line, and the only page that asks for nothing. "Import Art" appears on the last
    // panel, so the last panel had better be one whose job is to be the end: a recap of what this
    // window heard, read back before a 1-2 minute run starts. Every number on it comes from the
    // same `filledOn` the rail badges are painted from, so the page and the badge beside it can
    // never disagree about whether something was supplied.
    + panel("ready",
      `<p>That is everything this window asks for. <strong>Import Art</strong> below runs every page you filled in, in one pass.</p>`
      + `<div class="stbook-ready">` + READY_ROWS.map((r, i) =>
        `<div class="stbook-ready-row">`
        + `<span class="stbook-ready-name">${esc(r.label)}</span>`
        + `<span class="stbook-ready-value" data-ready="${i}"></span>`
        + `</div>`).join("") + `</div>`
      + `<p class="stbook-setup-note stbook-ready-none" hidden>Nothing is filled in yet. Step <strong>Back</strong> and point at least one of the pages above at a file.</p>`
      + `<p class="stbook-setup-note">Art you have already imported is skipped, so a re-run only writes what is new. To replace it instead — after a Stonetop update changes an illustration, or if an earlier import came out wrong — tick <strong>Force update</strong> in the corner below.${offerMaps ? ` Poster maps ignore it: they are always rewritten from whatever you supply.` : ""}</p>`)

    + `</div></div></div>`;

  // Every book the GM supplied, or (given a panel key) only the ones that panel asks for, which
  // is what its own Import button submits.
  const collectBooks = (dialog, key) => {
    const rootEl = dialog?.element ?? null;
    const out = [];
    for (const b of (key ? booksOn(key) : booksUsed)) {
      const f = rootEl?.querySelector(`[name="book-file-${b}"]`)?.files?.[0] ?? null;
      if (f) out.push({ book: b, file: f });
    }
    return out;
  };
  const collectForce = (dialog) => !!(dialog?.element?.querySelector?.('[name="force-update"]')?.checked);
  const NO_MAPS = { source: "images", pdfFile: null, picks: [] };
  const mapSourceOf = (rootEl) => String(rootEl?.querySelector?.('[name="map-source"]:checked')?.value ?? "images");
  // Which answer the GM gave, plus one pick per map they filled in. A PDF pick carries a
  // `page`; an image pick carries a `file` or a `path`. Only the block on screen is read, so
  // a row left over from switching answers can never quietly ride along into the run.
  const collectMaps = (dialog) => {
    const rootEl = dialog?.element ?? null;
    const empty = { ...NO_MAPS };
    if (!offerMaps || !rootEl) return empty;
    const source = mapSourceOf(rootEl);
    const picks = [];
    if (source === "pdf") {
      const pdfFile = rootEl.querySelector('[name="maps-pdf"]')?.files?.[0] ?? null;
      if (!pdfFile) return { ...empty, source };
      MANIFEST.maps.forEach((m, i) => {
        const page = Math.trunc(Number(rootEl.querySelector(`[name="map-page-${i}"]`)?.value));
        if (mapPageInPdf(page)) picks.push({ map: m, file: null, path: "", page });
      });
      return { source, pdfFile, picks };
    }
    MANIFEST.maps.forEach((m, i) => {
      const file = rootEl.querySelector(`[name="map-file-${i}"]`)?.files?.[0] ?? null;
      const path = String(rootEl.querySelector(`[name="map-path-${i}"]`)?.value ?? "").trim();
      if (file || path) picks.push({ map: m, file, path, page: 0 });
    });
    return { source, pdfFile: null, picks };
  };
  // What a page's own Import button submits: that page's inputs, and deliberately nothing any
  // other page holds. It is the same shape the footer's "Import Art" returns, so the run itself
  // needs to know nothing about which button started it. Force is the exception and belongs to
  // every one of them alike, which is why it is drawn in the footer next to them rather than on
  // any one page.
  const collectPage = (dialog, key) => ({
    books: key === "maps" ? [] : collectBooks(dialog, key),
    force: collectForce(dialog),
    maps: key === "maps" ? collectMaps(dialog) : NO_MAPS,
  });

  // The all-maps PDF the GM chose, parsed ONCE. The setup dialog reads it to preview each
  // row's page; section 7b renders the maps out of this very document rather than parsing a
  // ~40MB file a second time. `file` is the identity check: a GM who picks a different PDF
  // gets a fresh parse, and a stale in-flight parse for the old one is dropped on arrival.
  const mapsPdf = { file: null, doc: null, pages: 0 };
  // Is this row's page number one the chosen PDF actually has? The row shows no preview for a
  // page that isn't there, so the badge and what the run builds have to agree with that or the
  // dialog would be promising a map it then quietly fails on. A PDF the dialog never managed
  // to read (pages 0) stays permissive: section 7b parses it itself and guards the range there.
  const mapPageInPdf = (n) => Number.isFinite(n) && n >= 1 && (!mapsPdf.pages || n <= mapsPdf.pages);
  // Rendered page previews, keyed by page number and holding the PROMISE, so two rows on the
  // same page (or a number typed back and forth) share one render instead of racing.
  const mapThumbs = new Map();
  const mapThumb = (pageNum) => {
    if (!mapThumbs.has(pageNum)) mapThumbs.set(pageNum, (async () => {
      const page = await mapsPdf.doc.getPage(pageNum);
      try {
        const base = page.getViewport({ scale: 1 });
        const viewport = page.getViewport({ scale: Math.min(1, 124 / Math.max(1, base.width, base.height)) });
        const c = document.createElement("canvas");
        c.width = Math.max(1, Math.round(viewport.width)); c.height = Math.max(1, Math.round(viewport.height));
        const ctx = c.getContext("2d");
        // pdf.js paints no page background, so the parchment would come out on transparency.
        ctx.fillStyle = "#ffffff"; ctx.fillRect(0, 0, c.width, c.height);
        await page.render({ canvasContext: ctx, viewport }).promise;
        return c.toDataURL("image/webp", 0.7);
      } finally { page.cleanup?.(); }
    })());
    return mapThumbs.get(pageNum);
  };

  // Point every map row's thumbnail at the page its number currently names. Each row stamps
  // the page it is waiting on before awaiting, so a number changed mid-render doesn't get the
  // old page painted onto it when the slower one finally lands.
  const paintMapThumbs = (root) => {
    for (const img of root.querySelectorAll("[data-thumb]")) {
      const i = Number(img.dataset.thumb);
      const n = Math.trunc(Number(root.querySelector(`[name="map-page-${i}"]`)?.value));
      const usable = mapsPdf.doc && mapPageInPdf(n);
      img.dataset.pending = usable ? String(n) : "";
      if (!usable) { img.hidden = true; img.removeAttribute("src"); continue; }
      mapThumb(n).then((url) => {
        if (img.dataset.pending !== String(n)) return;
        img.src = url; img.hidden = false;
      }).catch(() => { img.hidden = true; });
    }
  };

  // Read the chosen all-maps PDF: page count into the status line and the rows' `max`, then
  // a preview per row. Everything here is cosmetic - a PDF that fails to parse still leaves
  // the run able to try it again in section 7b, where the failure is reported properly.
  const readMapsPdf = async (root, file) => {
    // A GM who picks a second PDF leaves the first one's worker holding ~40MB of decoded page.
    const stale = mapsPdf.doc;
    if (stale) Promise.resolve(stale.destroy()).catch(() => {});
    mapsPdf.file = file; mapsPdf.doc = null; mapsPdf.pages = 0;
    mapThumbs.clear();
    paintMapThumbs(root);
    const status = root.querySelector(".stbook-mapspdf-status");
    const say = (html) => { if (status) status.innerHTML = html; };
    if (!file) return say(`Usually named <code>All maps - 11 x 14.pdf</code>.`);
    say(`Reading &quot;${esc(file.name)}&quot;...`);
    let doc;
    try {
      const pdfjs = await loadPdfjs();
      doc = await pdfjs.getDocument({ data: await file.arrayBuffer(), isEvalSupported: false }).promise;
    } catch (e) {
      console.error("[Book II Art] all-maps PDF", e);
      if (mapsPdf.file === file) say(`&quot;${esc(file.name)}&quot; could not be read as a PDF.`);
      return;
    }
    if (mapsPdf.file !== file) { try { await doc.destroy(); } catch (_) {} return; } // a newer pick won
    mapsPdf.doc = doc; mapsPdf.pages = doc.numPages;
    say(`&quot;${esc(file.name)}&quot;: ${doc.numPages} page${doc.numPages === 1 ? "" : "s"}.`);
    for (const el of root.querySelectorAll('[name^="map-page-"]')) el.max = String(doc.numPages);
    paintMapThumbs(root);
  };

  const runButton = (root, key) => root.querySelector(`.form-footer [data-action="run-${key}"]`);

  // Show one panel: rail highlight, panel visibility, banner icon/title/optional/count, and
  // the column scrolled back to its top (a long panel otherwise hands the next one its
  // scroll offset). Mirrors module/utils/guide-rail.js — see the note at the top of §1.
  const showPanel = (root, key) => {
    const idx = Math.max(0, SETUP_SECTIONS.findIndex((s) => s.key === key));
    const sec = SETUP_SECTIONS[idx];
    for (const btn of root.querySelectorAll(".stbook-setup-tab")) {
      const on = btn.dataset.tab === sec.key;
      btn.closest(".stonetop-guide-toc-item")?.classList.toggle("is-active", on);
      if (on) btn.setAttribute("aria-current", "true"); else btn.removeAttribute("aria-current");
    }
    for (const el of root.querySelectorAll(".stbook-setup-section")) el.hidden = el.dataset.tab !== sec.key;
    const icon = root.querySelector(".stbook-setup-banner-icon");
    if (icon) icon.className = `fas ${sec.icon} stonetop-guide-banner-icon stbook-setup-banner-icon`;
    const title = root.querySelector(".stbook-setup-title");
    if (title) title.textContent = sec.title;
    const optional = root.querySelector(".stbook-setup-optional");
    if (optional) optional.hidden = !sec.optional;
    const count = root.querySelector(".stbook-setup-count");
    if (count) count.textContent = `${idx + 1} / ${SETUP_SECTIONS.length}`;
    const main = root.querySelector(".stbook-setup-main");
    if (main) main.scrollTop = 0;
    // The footer follows the panel. Back is DISABLED on the first panel rather than hidden, so
    // the row keeps its shape; Next and Import Art SWAP on the last one, so the primary action
    // turns up exactly when there is nothing left to fill in.
    const last = idx === SETUP_SECTIONS.length - 1;
    const back = root.querySelector(".form-footer .stbook-setup-back");
    if (back) back.disabled = idx === 0;
    const next = root.querySelector(".form-footer .stbook-setup-next");
    if (next) next.hidden = last;
    const submit = root.querySelector('.form-footer [data-action="ok"]');
    if (submit) submit.hidden = !last;
    // ...and a page's own Import button belongs to that page alone, so only this one shows.
    for (const s of SETUP_SECTIONS) {
      if (!s.runLabel) continue;
      const run = runButton(root, s.key);
      if (run) run.hidden = s.key !== sec.key;
    }
  };

  // How much a panel has been given. Books count a file per field; maps count a row as supplied
  // if EITHER of its two inputs is, which is the same test collectMaps applies.
  const filledOn = (root, key) => {
    if (key !== "maps") return booksOn(key).filter((b) => root.querySelector(`[name="book-file-${b}"]`)?.files?.length).length;
    if (!offerMaps) return 0;
    // Counted the way collectMaps reads them, so the badge can never promise a map the run
    // won't build: in PDF mode a page number counts for nothing until the PDF itself is in.
    if (mapSourceOf(root) === "pdf") {
      return !root.querySelector('[name="maps-pdf"]')?.files?.length ? 0
        : MANIFEST.maps.filter((_m, i) => mapPageInPdf(Math.trunc(Number(root.querySelector(`[name="map-page-${i}"]`)?.value)))).length;
    }
    return MANIFEST.maps.filter((_m, i) =>
      root.querySelector(`[name="map-file-${i}"]`)?.files?.length
      || String(root.querySelector(`[name="map-path-${i}"]`)?.value ?? "").trim()).length;
  };

  // The rail badges, and whether each page's own Import button can do anything. Both off the one
  // count, so the number a GM can see and the test that decides whether the button is live can
  // never disagree: an enabled "Import these maps" over an empty page would open a 1-2 minute
  // window that imports nothing.
  const paintBadges = (root) => {
    for (const s of SETUP_SECTIONS) {
      if (!s.badge && !s.runLabel) continue;
      const n = filledOn(root, s.key);
      const el = s.badge ? root.querySelector(`[data-badge="${s.badge}"]`) : null;
      if (el) el.textContent = n ? String(n) : "";
      const run = s.runLabel ? runButton(root, s.key) : null;
      if (run) run.disabled = !n;
    }
    paintReady(root);
  };

  // The last page's recap, read back off the same inputs. Painted from paintBadges rather than
  // from showPanel, so a file chosen on a page the GM then steps AWAY from still lands here: the
  // recap has to be right when it is first looked at, not only when it is next changed.
  const paintReady = (root) => {
    let supplied = 0;
    READY_ROWS.forEach((r, i) => {
      // A book is one file field, so it is a yes or a no; maps are a row apiece, so they count.
      const n = r.book != null
        ? (root.querySelector(`[name="book-file-${r.book}"]`)?.files?.length ? 1 : 0)
        : filledOn(root, r.key);
      supplied += n;
      const el = root.querySelector(`[data-ready="${i}"]`);
      if (!el) return;
      el.textContent = r.book != null ? (n ? "supplied" : "not supplied")
        : n ? `${n} of ${MANIFEST.maps.length}` : "none";
      el.classList.toggle("is-on", !!n);
    });
    // Said once, at the bottom, rather than as a disabled Import Art: the run already answers an
    // empty sheet with "nothing chosen", and a dead primary button on the finish line reads as
    // something broken rather than as something not yet filled in.
    const none = root.querySelector(".stbook-ready-none");
    if (none) none.hidden = supplied > 0;
  };

  const picks = await foundry.applications.api.DialogV2.wait({
    classes: [...DLG_CLASSES, "stbook-setup-dialog"],
    window: { title: "Import Book Art", resizable: true },
    // A height is mandatory here, not a preference: the rail layout fills the height it is
    // given, and a DialogV2 left on "auto" would size itself to the tallest panel and undo
    // the whole point of the rail. Resizable, so a GM on a short screen can still shrink it.
    position: { width: 700, height: 600 },
    // An element, not a string. DialogV2 runs a string through foundry.utils.cleanHTML,
    // whose attribute allowlist has no `accept` — so the string form silently dropped the
    // PDF/image filter off every file field. An attribute-less <div> is passed through
    // verbatim by the same API (see DialogV2#_initializeApplicationOptions).
    content: Object.assign(document.createElement("div"), { innerHTML: setupHtml }),
    render: (_event, dialog) => {
      const root = dialog?.element;
      // `render` fires per render pass; the listeners below are delegated and would stack.
      if (!root || root.dataset.stbookWired) return;
      root.dataset.stbookWired = "1";
      root.addEventListener("click", (ev) => {
        const btn = ev.target?.closest?.(".stbook-setup-tab");
        if (btn) { ev.preventDefault(); showPanel(root, btn.dataset.tab); return; }
        // Which panel we're on is read off the rail rather than tracked in a variable of its
        // own: the rail is what showPanel already keeps correct, so the two can't drift.
        const step = ev.target?.closest?.(".stbook-setup-back, .stbook-setup-next");
        if (!step) return;
        ev.preventDefault();
        const at = SETUP_SECTIONS.findIndex((s) => s.key === root.querySelector('.stbook-setup-tab[aria-current="true"]')?.dataset.tab);
        const to = SETUP_SECTIONS[Math.max(0, at) + (step.classList.contains("stbook-setup-next") ? 1 : -1)];
        if (to) showPanel(root, to.key);
      });
      // `change` covers the file fields (which never fire `input`), `input` the path boxes.
      root.addEventListener("change", () => paintBadges(root));
      root.addEventListener("input", () => paintBadges(root));
      if (offerMaps) {
        // Show the block that answers "which do you have?", read the all-maps PDF when one is
        // chosen, and re-preview a row whose page number is retyped.
        const syncMapMode = () => {
          const mode = mapSourceOf(root);
          for (const el of root.querySelectorAll(".stbook-map-mode")) el.hidden = el.dataset.mode !== mode;
        };
        root.addEventListener("change", (ev) => {
          if (ev.target?.name === "map-source") syncMapMode();
          if (ev.target?.name === "maps-pdf") readMapsPdf(root, ev.target.files?.[0] ?? null);
        });
        root.addEventListener("input", (ev) => {
          if (/^map-page-\d+$/.test(ev.target?.name ?? "")) paintMapThumbs(root);
        });
        syncMapMode();
      }
      // Enter inside the sheet must never submit this form. The implicit submitter is whichever
      // submit button comes FIRST in the DOM, and on a middle panel that is a hidden Import Art
      // (which would launch the whole 1-2 minute run with half the sheet unfilled) or, failing
      // that, Cancel (which would throw away the files already chosen). Blur a field instead,
      // which fires `change`, so the badge and the page previews still update. A real button
      // keeps its own Enter, because that is a click.
      root.addEventListener("keydown", (ev) => {
        if (ev.key !== "Enter" || ev.target?.closest?.("button")) return;
        ev.preventDefault();
        ev.target?.blur?.();
      });
      // Wear the Welcome guide's nav-button skin. DialogV2 renders its own `<footer
      // class="form-footer">` with no hook of ours on it, so the class goes on here rather
      // than the alternative of re-declaring that skin under a second name.
      const footer = root.querySelector(".form-footer");
      footer?.classList.add("stonetop-guide-nav");
      // Force update, in the corner beside Cancel. It lives in the footer rather than on a page
      // because it does not belong to a page: it changes what EVERY import button in this row
      // does, including the three per-page ones, and a tick-box on a panel is invisible from the
      // page you are actually importing from. Built here for the same reason Back and Next are —
      // a declared DialogV2 button submits — and inserted after Cancel so the two quiet things
      // share the left corner. The full explanation rides as a tooltip and is also written out
      // on the last page; the footer only has room to name it.
      if (footer && !footer.querySelector(".stbook-setup-force")) {
        const force = document.createElement("label");
        force.className = "stbook-setup-force";
        force.dataset.tooltip = "Re-parse the books and replace art you have already imported, instead of skipping what is already on disk. Turn it on to refresh art after a Stonetop update, or if an earlier import came out wrong.";
        const box = document.createElement("input");
        box.type = "checkbox";
        box.name = "force-update";
        const text = document.createElement("span");
        text.textContent = "Force update";
        force.append(box, text);
        const cancel = footer.querySelector(".stbook-setup-cancel");
        if (cancel) cancel.after(force); else footer.prepend(force);
      }
      // Build Back and Next by hand, deliberately WITHOUT a `data-action` (see the buttons
      // list above: that attribute is exactly what would make them submit the dialog). The
      // arrow is the guide's shared masked glyph, and it sits before the label on Back and
      // after it on Next, so each points the way it takes you.
      if (footer && !footer.querySelector(".stbook-setup-next")) {
        const navButton = (cls, label, backwards) => {
          const button = document.createElement("button");
          button.type = "button";
          button.className = cls;
          const arrow = document.createElement("i");
          arrow.className = "stonetop-nav-arrow" + (backwards ? " stonetop-nav-arrow--back" : "");
          const text = document.createElement("span");
          text.textContent = label;
          button.append(...(backwards ? [arrow, text] : [text, arrow]));
          return button;
        };
        const submit = footer.querySelector('[data-action="ok"]');
        footer.insertBefore(navButton("stbook-setup-back", "Back", true), submit);
        footer.insertBefore(navButton("stbook-setup-next", "Next", false), submit);
      }
      // Paint the footer for the panel we open on, rather than declaring that state twice, and
      // settle the badges and the page Import buttons against an empty sheet: every one of them
      // starts out with nothing to import, and only paintBadges knows how to say so.
      showPanel(root, SETUP_SECTIONS[0].key);
      paintBadges(root);
    },
    // A wizard footer, in the window's OWN button row rather than a second band above it.
    //
    // Back and Next are declared here, as DialogV2 buttons with `type: "button"`. That is what
    // makes it possible at all: DialogV2 renders its buttons as `type="submit"` inside its form
    // and reads `event.submitter` on submit, so a normal footer button would start the 1-2
    // minute import instead of turning the page. A `type="button"` renders into the same row,
    // in the same skin, and submits nothing — leaving the stepping to showPanel.
    //
    // Import Art is HIDDEN until the last panel, so the primary action appears once there is
    // nothing left to fill in. Hidden, never removed: DialogV2's own submit handler walks every
    // declared action and disables its button, and would throw on one that isn't in the DOM.
    // The same goes for the per-page Import buttons, which are hidden on every panel but their
    // own. Only the REAL outcomes are declared. Back and Next are built in the render hook and
    // inserted before the submit, because a DialogV2 button cannot be made to not submit:
    // `_initializeApplicationOptions` registers EVERY declared button as an ApplicationV2
    // action bound to `_onClickButton`, so clicking one resolves the dialog whatever its
    // `type` is. (`type: "button"` only stops the form's own implicit submit, which is a
    // different path.) ApplicationV2 dispatches on `[data-action]` alone, so a plain button
    // without that attribute is simply not its business. That is also why the per-page buttons
    // are declared here rather than dropped into the panel body they belong to: a button inside
    // the content could not end the dialog, and everything downstream of `picks` is written
    // against a dialog that has closed with an answer.
    //
    // Declaration order is layout order: Cancel in the left corner (with the Force update
    // tick-box inserted beside it), then Back/Next inserted before Import Art, then the page
    // buttons after it — so whichever import applies to the page you are on is the rightmost
    // thing in the row, and there is never more than one.
    buttons: [
      { action: "cancel", label: "Cancel", class: "stbook-setup-cancel", callback: () => null },
      { action: "ok", label: "Import Art", default: true, class: "stbook-setup-submit", callback: (event, button, dialog) => ({ books: collectBooks(dialog), force: collectForce(dialog), maps: collectMaps(dialog) }) },
      ...SETUP_SECTIONS.filter((s) => s.runLabel).map((s) => ({
        action: `run-${s.key}`, label: s.runLabel, class: "stbook-setup-run",
        callback: (event, button, dialog) => collectPage(dialog, s.key),
      })),
    ],
    rejectClose: false,
  });
  const bookFiles = Array.isArray(picks?.books) ? picks.books : [];
  const forceUpdate = !!picks?.force;
  // Collected up front with everything else now, rather than in a second dialog after the
  // PDFs validate. The maps are user-supplied images and touch nothing the books do, so
  // nothing about them depended on that ordering.
  const mapChoice = picks?.maps ?? { source: "images", pdfFile: null, picks: [] };
  const mapPicks = Array.isArray(mapChoice.picks) ? mapChoice.picks : [];
  // Books OR maps is enough. The poster maps are the GM's own files and share nothing with the
  // book extraction, so "I already imported the art, I just want my maps" is a real and common
  // way to use this — and refusing it meant re-picking a 40MB PDF to do nothing with. Only a
  // run with neither is a mistake worth stopping for.
  if (!bookFiles.length && !mapPicks.length) {
    return notify.warn("Import Book Art: nothing chosen. Point it at a book PDF, or supply your maps under \"Poster maps\".");
  }
  log("books supplied:", bookFiles.map((p) => bookLabel(p.book)).join(", ") || "none", forceUpdate ? "(force update)" : "");
  log(`maps requested (${mapChoice.source}): ${mapPicks.length ? mapPicks.map((p) => p.map.slug + (p.page ? ` p${p.page}` : "")).join(", ") : "none"}`);

  // ---- 2. load Foundry's bundled pdf.js -----------------------------------
  await progress.open("Loading the PDF engine...");
  let pdfjs;
  try { pdfjs = await loadPdfjs(); }
  catch (e) { console.error(e); await progress.close(); return notify.error("Import Book Art: could not load Foundry's pdf.js. See console."); }
  const { OPS } = pdfjs;

  // ---- 2b. spreads vs 1-up -------------------------------------------------
  // EVERY page number and rect in the manifest names a place on a "spreads" sheet: the
  // landscape page that carries two printed pages side by side, which is the edition the books
  // are sold as and the one this macro was measured against. The free GM playbook is also
  // published 1-up — one printed page per portrait sheet — and that is the file a GM who
  // downloads it today is most likely to hand us.
  //
  // Read as if it were a spread, a 1-up file is not slightly wrong, it is wrong twice over: its
  // page 12 is a different page of the book altogether, and any rect reaching past the middle of
  // a spread falls off the right edge of a 396pt sheet and rasterises as blank white paper.
  //
  // The fix is to put the sheet back together. Measured against each other, a 1-up page PAIR
  // butted side by side reproduces its spread to within half a point, so `sheetPagesFor` names
  // the pair and `renderRegion` draws both onto one canvas before the rect is applied. Only the
  // two flowcharts need a rect of their own (`oneUp.rect` in the manifest): their spread runs its
  // text block right up to the gutter, where the booklet insets it, so the same numbers cannot
  // describe both. See the README, "The GM playbook's two editions".
  async function pdfLayout(doc) {
    // Read across the file, not off page 1. Both rulebooks open on a single half-width cover
    // (396x612, portrait) and close on another, with 300-odd landscape spreads in between, so a
    // file judged by its first page alone is called 1-up and refused over its wrapper: Book I and
    // Book II both skipped, "no usable book PDF provided", while the playbook (whose spreads
    // edition has no separate cover) imported fine. Covers are the exception in every edition of
    // these books, so sample the paper BETWEEN them and let the majority answer.
    const inner = doc.numPages > 2 ? [2, doc.numPages - 1] : [1, doc.numPages];
    const span = inner[1] - inner[0];
    const probes = [...new Set(Array.from({ length: 5 }, (_, i) => inner[0] + Math.round((i * span) / 4)))];
    let portrait = 0, landscape = 0;
    const shape = {};
    for (const p of probes) {
      let vp;
      try {
        const page = await doc.getPage(p);
        try { vp = page.getViewport({ scale: 1 }); } finally { page.cleanup?.(); }
      } catch (_) { continue; }
      // Portrait means one printed page per sheet. A spread is always wider than it is tall
      // (792x612 letter); no edition of these books prints a portrait spread.
      const tall = vp.width < vp.height;
      if (tall) portrait++; else landscape++;
      shape[tall ? "portrait" : "landscape"] ??= { width: vp.width, height: vp.height };
    }
    const oneUp = portrait > landscape;
    // The paper the verdict was actually read off, so the log names dimensions a GM can check.
    // A file that answered nothing at all (every probe threw) reads as spreads, which is the
    // calibrated edition: it is then the page-count check and the per-image extraction that fail
    // and say so, rather than a whole book refused on no evidence.
    const { width = 0, height = 0 } = shape[oneUp ? "portrait" : "landscape"] ?? {};
    // The evidence rides out WITH the verdict instead of being logged from in here, which keeps
    // this function free of every other name in the macro. That is what lets it be lifted out of
    // the shipped command and run on its own, which is how the tests check it; a `log()` call
    // added here would break that lift with a ReferenceError. Keep it self-contained.
    return { oneUp, width, height, offset: 0, probes, portrait, landscape };
  }

  // Sheet 1 of the paper is not page 1 of a 1-up file: the current playbook booklet opens with a
  // cover, so every sheet sits one page later than the arithmetic alone would say. Rather than
  // assume any particular front matter, find the one page we can name by the words printed on it
  // and read the offset off that. A file we cannot anchor keeps offset 0 and says so, which is
  // the same answer the arithmetic would have given — never a silent guess at a different one.
  const ONE_UP_ANCHOR = {
    // The core loop's own page: its heading plus the first box of the chart. Neither alone is
    // enough — the heading is also in the playbook's own agenda page and its contents list, and
    // that agenda page prints "establish THE situation", which is why the box's exact wording is
    // what separates them. Together they match this one page of the booklet and no other.
    sheet: 12, half: 0,
    words: ["core loop", "establish situation"],
  };
  async function oneUpOffset(doc, book) {
    const nominal = 2 * ONE_UP_ANCHOR.sheet + ONE_UP_ANCHOR.half;
    for (let p = 1; p <= doc.numPages; p++) {
      let text;
      try {
        const page = await doc.getPage(p);
        // Collapsed to single spaces: pdf.js hands back one item per run of glyphs, and whether
        // a two-word label arrives as one item, as two, or as one with a trailing space is a
        // detail of the file. A phrase must not stop matching because of it.
        try { text = (await page.getTextContent()).items.map((i) => i.str ?? "").join(" ").replace(/\s+/g, " ").toLowerCase(); }
        finally { page.cleanup?.(); }
      } catch (_) { continue; }
      if (!ONE_UP_ANCHOR.words.every((w) => text.includes(w))) continue;
      const off = p - nominal;
      // A plausible amount of front matter only. A hit further out than that is more likely a
      // reprint we do not understand than a cover, and its page numbers would be wrong anyway.
      if (Math.abs(off) > 6) { log(`${bookLabelCap(book)}: anchor page found at ${p}, too far from ${nominal} to trust; assuming no front matter`); return 0; }
      return off;
    }
    log(`${bookLabelCap(book)}: could not find the core-loop page to align this 1-up file; assuming no front matter`);
    return 0;
  }

  // The page (spreads) or pages (1-up, left then right) a manifest sheet number resolves to.
  const sheetPagesFor = (book, sheet) => {
    const layout = layoutByBook.get(book);
    if (!layout?.oneUp) return [sheet];
    const left = 2 * sheet + layout.offset;
    return [left, left + 1];
  };

  // A row may carry a second rect measured against the 1-up edition; see pdfLayout.
  const rectFor = (r) => (layoutByBook.get(r.book ?? 2)?.oneUp && r.oneUp?.rect) ? r.oneUp.rect : r.rect;

  // ---- 3. load + validate each supplied book PDF --------------------------
  // Read every book the user provided into its own pdf.js document, keyed by book.
  // A page-count mismatch warns (and offers to continue) rather than aborting the
  // whole run, so one odd edition doesn't block the others.
  const pdfByBook = new Map();
  // How each supplied PDF lays its printed pages out, keyed the same way. See `sheetPagesFor`:
  // every page number and rect in the manifest is written against a "spreads" sheet, and a book
  // handed to us one printed page per sheet has to be put back together before they mean anything.
  const layoutByBook = new Map();
  for (const { book, file } of bookFiles) {
    log(`${bookLabelCap(book)} PDF:`, file.name, (file.size / 1e6).toFixed(1) + " MB");
    progress.phase(`Reading ${bookLabel(book)} PDF...`, file.name);
    let doc;
    try {
      // isOffscreenCanvasSupported:false forces pdf.js to hand back raw pixel data
      // (not ImageBitmap), so image masks/images can be read directly.
      const buf = await file.arrayBuffer();
      doc = await pdfjs.getDocument({ data: buf, isOffscreenCanvasSupported: false, isEvalSupported: false }).promise;
    } catch (e) { console.error(e); notify.error(`Import Book Art: the file you gave for ${bookLabel(book)} could not be read as a PDF; skipping it.`); continue; }
    // Which edition this is, measured off the shape of the paper rather than inferred from the
    // page count: a printing is free to wrap the paper in a cover or two, and the count moves when
    // it does. The covers are why it is measured off several pages and not just the first one.
    const layout = await pdfLayout(doc);
    // Said out loud on BOTH verdicts. The page-1 bug was invisible from the console: the run named
    // the edition it had settled on but never the evidence, so a GM could report the refusal and
    // nothing about the file that earned it. The pages sampled and the tally make a mis-detection
    // diagnosable from a pasted log, without asking anyone for a 60 MB PDF.
    log(`${bookLabelCap(book)} edition: ${layout.oneUp ? "1-up" : "spreads"}, ${layout.width}x${layout.height}pt, read off pages ${layout.probes.join("/")} (${layout.portrait} portrait, ${layout.landscape} landscape)`);
    if (layout.oneUp && !BOOKS[book]?.oneUp) {
      // Refused, not attempted. Every row of a rulebook names its picture by size and placement
      // on a numbered page of the spreads edition; on a 1-up file each of those numbers points
      // at a different page, so the run would not fail — it would fill the world with the wrong
      // pictures, which is far worse than not running.
      notify.error(`Import Book Art: that ${bookLabel(book)} file is the 1-up edition (one page per sheet). This needs the "spreads" edition, where two pages sit side by side; skipping it.`);
      log(`${bookLabelCap(book)}: 1-up edition supplied; skipped`);
      continue;
    }
    const expected = bookExpected(book);
    // A 1-up file carries two sheets where the spreads edition carries one, plus whatever covers
    // the printing adds (the playbook booklet currently has one, for 28 sheets over 24 of paper).
    // So the page count is checked against a RANGE for those, and only a file outside it asks.
    const [lo, hi] = !expected ? [0, Infinity] : layout.oneUp ? [2 * expected, 2 * expected + 4] : [expected, expected];
    log(`${bookLabelCap(book)} pages:`, doc.numPages, `(expected ${expected}${layout.oneUp ? `, read as a 1-up edition so ${lo}-${hi}` : ""})`);
    if (expected && (doc.numPages < lo || doc.numPages > hi)) {
      if (CONFIG.STRICT_PAGES) { notify.error(`Import Book Art: ${bookLabel(book)} has an unexpected page count (${doc.numPages}); skipping it.`); continue; }
      await progress.close();
      const go = await foundry.applications.api.DialogV2.confirm({
        classes: DLG_CLASSES,
        window: { title: "Import Book Art: Unexpected PDF" },
        content: `<p>${bookLabelCap(book)} is calibrated for the ${expected}-page "spreads" edition${layout.oneUp ? ` (or the ${2 * expected}-page 1-up one)` : ""}. Your file has ${doc.numPages} pages, so its images may not match. Use it anyway?</p>`,
      });
      await progress.open("Reading your PDFs...");
      if (!go) continue;
    }
    // Where the paper starts in a 1-up file, so a sheet number can be turned into its two pages.
    if (layout.oneUp) {
      layout.offset = await oneUpOffset(doc, book);
      log(`${bookLabelCap(book)} is a 1-up edition: sheet N is pages ${2 + layout.offset}/${3 + layout.offset} for sheet 1`);
    }
    pdfByBook.set(book, doc);
    layoutByBook.set(book, layout);
  }
  // Is there an ART half to this run at all? Everything from section 5b to section 7 is the
  // book extraction and the document wiring it feeds; with no readable book PDF all of it is
  // skipped and the run is just the poster maps. Gated on the PDFs that actually LOADED, not
  // on what was chosen, so a book file that turns out to be unreadable degrades to the same
  // maps-only run rather than failing every image against a PDF that isn't there.
  const artRun = pdfByBook.size > 0;
  if (!artRun && !mapPicks.length) { await progress.close(); return notify.warn("Import Book Art: no usable book PDF provided."); }

  // The poster maps used to be asked for HERE, in a second dialog wedged between the PDF
  // validation and the extraction. They are now the setup dialog's "Poster maps" panel
  // (section 1) — nothing between here and section 7b needs them, and pausing a run that
  // had already read two ~300-page PDFs to ask one more optional question was the worst
  // possible moment for it. Everything from here on is non-interactive, so the progress
  // window can stay up unbroken.
  progress.phase("Preparing...");

  // ---- 4. PDF image extraction (op-list walk -> raw stencil) ---------------
  const mul = (m, n) => [m[0]*n[0]+m[2]*n[1], m[1]*n[0]+m[3]*n[1], m[0]*n[2]+m[2]*n[3], m[1]*n[2]+m[3]*n[3], m[0]*n[4]+m[2]*n[5]+m[4], m[1]*n[4]+m[3]*n[5]+m[5]];
  const resolveObj = (page, key) => (page.objs.has(key) ? Promise.resolve(page.objs.get(key)) : new Promise((r) => page.objs.get(key, r)));

  // Scan a page: every painted image with its native size + placement (fitz top-left points).
  async function scanPage(page) {
    const H = page.view[3] - page.view[1];
    const opList = await page.getOperatorList();
    let ctm = [1, 0, 0, 1, 0, 0]; const stack = []; const imgs = [];
    for (let i = 0; i < opList.fnArray.length; i++) {
      const fn = opList.fnArray[i], a = opList.argsArray[i];
      if (fn === OPS.save) stack.push(ctm.slice());
      else if (fn === OPS.restore) ctm = stack.pop() || [1, 0, 0, 1, 0, 0];
      else if (fn === OPS.transform) ctm = mul(ctm, a);
      else if (fn === OPS.paintImageMaskXObject || fn === OPS.paintImageXObject || fn === OPS.paintInlineImageXObject) {
        const arg = a[0];
        const isMask = fn === OPS.paintImageMaskXObject;
        const hpt = Math.hypot(ctm[2], ctm[3]);
        const px = Math.round(ctm[4]), py = Math.round(H - (ctm[5] + hpt));
        let w, h, key = null, obj = null;
        if (arg && typeof arg === "object" && arg.data && typeof arg.data !== "string") { obj = arg; w = arg.width; h = arg.height; } // inline
        else if (arg && typeof arg === "object" && typeof arg.data === "string") { key = arg.data; w = arg.width; h = arg.height; } // mask via objs
        else if (typeof arg === "string") { key = arg; obj = await resolveObj(page, key); w = obj?.width; h = obj?.height; } // named xobject
        if (!w || !h) continue;
        imgs.push({ page, isMask, key, obj, w, h, px, py });
      }
    }
    return imgs;
  }

  // Reconstruct an image object into a native-size canvas (black-on-white for stencils).
  function imageToCanvas(obj, isMask) {
    const w = obj.width, h = obj.height, d = obj.data;
    const canvas = document.createElement("canvas");
    canvas.width = w; canvas.height = h;
    const ctx = canvas.getContext("2d");
    const out = new Uint8ClampedArray(w * h * 4);
    const ratio = d.length / (w * h);
    if (isMask || ratio < 0.9) {                       // 1-bit stencil: paint where bit==0
      const rowBytes = Math.ceil(w / 8);
      for (let y = 0; y < h; y++) for (let x = 0; x < w; x++) {
        const bit = (d[y * rowBytes + (x >> 3)] >> (7 - (x & 7))) & 1;
        const v = bit === 0 ? 0 : 255; const o = (y * w + x) * 4; out[o] = out[o+1] = out[o+2] = v; out[o+3] = 255;
      }
    } else if (ratio >= 3.9) { for (let i = 0; i < w * h; i++) { out[i*4]=d[i*4]; out[i*4+1]=d[i*4+1]; out[i*4+2]=d[i*4+2]; out[i*4+3]=255; } } // RGBA over white
    else if (ratio >= 2.9) { for (let i = 0; i < w * h; i++) { out[i*4]=d[i*3]; out[i*4+1]=d[i*3+1]; out[i*4+2]=d[i*3+2]; out[i*4+3]=255; } }     // RGB
    else { for (let i = 0; i < w * h; i++) { out[i*4]=out[i*4+1]=out[i*4+2]=d[i]; out[i*4+3]=255; } }                                           // gray
    ctx.putImageData(new ImageData(out, w, h), 0, 0);
    return canvas;
  }

  // Rasterise a rect of a page (`want.rect`, in the same fitz top-left points as every
  // row's `bbox`) at want.dpi. The opposite of imageToCanvas: that lifts an image object
  // out of the page and so never picks up text, which is exactly what the illustrations
  // need (their body copy is laid OVER them) and exactly what the printed maps must not
  // do — their location labels ARE text. Rendering the region bakes the labels in.
  //
  // `want.mask` white-boxes rects (same coordinate space) after the render: the Book II
  // spread titles sit inside the map's own bounds, on bare white, so they cannot be
  // cropped off without cutting map, but they can be painted out losslessly.
  //
  // `page` may also be the PAIR of 1-up pages that together are one spread (see pdfLayout). They
  // are laid down left to right, each at its own width, which is what makes a rect authored
  // against the spreads edition mean the same thing on a booklet — including the three regional
  // maps, whose art crosses the gutter and so is genuinely half on each page.
  async function renderRegion(page, want) {
    const pages = Array.isArray(page) ? page : [page];
    const scale = (want.dpi || CONFIG.PAGEMAP_DPI) / 72;
    const [x0, y0, x1, y1] = want.rect;
    const canvas = document.createElement("canvas");
    canvas.width = Math.round((x1 - x0) * scale);
    canvas.height = Math.round((y1 - y0) * scale);
    const ctx = canvas.getContext("2d");
    // pdf.js paints no page background, so without this the crop carries alpha into the
    // WebP (and every un-inked part of the map would come out transparent, not paper).
    ctx.fillStyle = "#ffffff";
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    // Render the whole page through a translation that puts rect's top-left at the canvas
    // origin; everything outside the canvas is simply clipped away by its bounds.
    //
    // A PAIR cannot do that twice into the same context. pdf.js opens every render by filling
    // the WHOLE target canvas with its background — `CanvasGraphics#beginDrawing` runs
    // `fillStyle = background || "#ffffff"; fillRect(0, 0, width, height)` before it draws a
    // single glyph — so the second page of a sheet does not join the first, it ERASES it. That
    // is what came back from a stitched booklet: blank down the left half, which is the whole of
    // the core-loop chart and the left page of all three regional maps. So a pair renders one
    // page at a time onto a sheet of its own and each is composited in. Its own canvas rather
    // than pdf.js's `background: "rgba(0,0,0,0)"` (a transparent fill would also spare the pixels
    // underneath) because a page that draws itself and is then copied depends on nothing but
    // drawImage — no render option that a later pdf.js could stop honouring, silently, by
    // going back to painting the sheet white.
    //
    // The lone-page case keeps rendering straight into the crop, at the exact fractional offset:
    // that is every row of both rulebooks, and there is no reason to re-cut them a pixel over.
    let sheetX = 0;
    for (const p of pages) {
      const viewport = p.getViewport({ scale });
      const dx = (sheetX - x0) * scale, dy = -y0 * scale;
      if (pages.length === 1) {
        await p.render({ canvasContext: ctx, viewport, transform: [1, 0, 0, 1, dx, dy] }).promise;
      } else {
        const one = document.createElement("canvas");
        one.width = Math.ceil(viewport.width);
        one.height = Math.ceil(viewport.height);
        await p.render({ canvasContext: one.getContext("2d"), viewport }).promise;
        ctx.drawImage(one, Math.round(dx), Math.round(dy));
        // Released at once rather than left to GC, for the reason `swap` gives: a page-sized
        // buffer at 300 dpi is ~17 MB, and the loop is about to allocate the next one.
        one.width = one.height = 0;
      }
      sheetX += viewport.width / scale;
    }
    ctx.fillStyle = "#ffffff";
    for (const m of want.mask ?? []) ctx.fillRect((m[0] - x0) * scale, (m[1] - y0) * scale, (m[2] - m[0]) * scale, (m[3] - m[1]) * scale);
    return canvas;
  }

  // Hand a canvas off to whatever replaced it and release the old one's pixel buffer at once,
  // for the same reason the extraction loop zeroes its final lift (see there): a chain of
  // lift -> rescale -> crop -> crop otherwise leaves every intermediate alive until GC gets
  // round to it, and a lift from a higher-resolution printing is several times the size of the
  // file it becomes.
  // Returns the replacement, so a call reads as the assignment it is.
  const swap = (old, next) => { if (next !== old) { old.width = old.height = 0; } return next; };

  function downscale(canvas, maxDim) {
    const long = Math.max(canvas.width, canvas.height);
    if (long <= maxDim) return canvas;
    const s = maxDim / long;
    const c2 = document.createElement("canvas");
    c2.width = Math.round(canvas.width * s); c2.height = Math.round(canvas.height * s);
    const ctx = c2.getContext("2d"); ctx.imageSmoothingEnabled = true; ctx.imageSmoothingQuality = "high";
    ctx.drawImage(canvas, 0, 0, c2.width, c2.height);
    return c2;
  }

  // Cut a sub-rectangle out of a lifted illustration. `crop` is [fx0,fy0,fx1,fy1] in
  // fractions of the source canvas (0..1), so it is resolution-independent — a "People of
  // Stonetop" person row can carve one portrait out of an illustration that holds several
  // figures. The picker draws these rects on the very same lifted stencil (its thumbnail),
  // so the fractions map 1:1. Applied BEFORE downscale, so the crop keeps full resolution
  // and only then gets capped. Clamps to the canvas and never yields a zero-size tile.
  function cropCanvas(canvas, crop) {
    const W = canvas.width, H = canvas.height;
    const cl = (v) => Math.min(1, Math.max(0, v));
    const x0 = Math.round(cl(crop[0]) * W), y0 = Math.round(cl(crop[1]) * H);
    const x1 = Math.round(cl(crop[2]) * W), y1 = Math.round(cl(crop[3]) * H);
    const w = Math.max(1, x1 - x0), h = Math.max(1, y1 - y0);
    const c = document.createElement("canvas");
    c.width = w; c.height = h;
    c.getContext("2d").drawImage(canvas, x0, y0, w, h, 0, 0, w, h);
    return c;
  }

  const toBlob = (canvas) => new Promise((res) => canvas.toBlob(res, "image/webp", CONFIG.QUALITY));

  // Race a hang-prone await (pdf.js object resolution, page render, file upload) against a
  // watchdog so a promise that never settles throws instead of freezing the whole import.
  const withTimeout = (p, label, ms = CONFIG.OP_TIMEOUT_MS) => Promise.race([
    Promise.resolve(p),
    new Promise((_, rej) => setTimeout(() => rej(new Error(`timed out after ${Math.round(ms / 1000)}s: ${label}`)), ms)),
  ]);

  // ---- 4b. poster-map helpers ----------------------------------------------
  // Write a finished map canvas out as WebP under ROOT/assets/maps and return { src, w, h }
  // for the Scene. The shared tail of both ways in: a supplied image file, or a page of the
  // GM's all-maps PDF. The long side is capped here as well as at each source, so whichever
  // one grows a new path the file on disk still can't exceed MAP_MAXDIM.
  async function uploadMapCanvas(map, canvas) {
    const c = downscale(canvas, CONFIG.MAP_MAXDIM);
    const blob = await toBlob(c);
    if (!blob) throw new Error("empty blob");
    const dir = `${CONFIG.ROOT}/assets/maps`;
    const name = map.out.slice(map.out.lastIndexOf("/") + 1);
    // Same falsy-means-rejected rule as the illustration uploads (see there): a Scene built around
    // a background that was never written is worse than no Scene at all, and this one throws
    // straight into the per-map failure list.
    const res = await FP.upload("data", dir, new File([blob], name, { type: "image/webp" }), { overwrite: true }, { notify: false });
    if (!res) throw new Error("the server rejected the upload");
    if (typeof res.path === "string" && res.path) noteServed(res.path);
    return { src: srcOf(map.out), w: c.width, h: c.height };
  }

  // Convert a user-supplied map image to WebP (long side capped, never upscaled)
  // and upload it under ROOT/assets/maps; returns { src, w, h } for the scene.
  async function uploadMapFile(map, file) {
    const bmp = await createImageBitmap(file);
    try {
      const s = Math.min(1, CONFIG.MAP_MAXDIM / Math.max(bmp.width, bmp.height));
      const c = document.createElement("canvas");
      c.width = Math.max(1, Math.round(bmp.width * s)); c.height = Math.max(1, Math.round(bmp.height * s));
      const ctx = c.getContext("2d"); ctx.imageSmoothingEnabled = true; ctx.imageSmoothingQuality = "high";
      ctx.drawImage(bmp, 0, 0, c.width, c.height);
      return await uploadMapCanvas(map, c);
    } finally { bmp.close?.(); }
  }

  // The longest pixel edge of any image a page paints, read straight off the operator list.
  // Deliberately NOT scanPage: that resolves each image object, which decodes a 14-megapixel
  // map plate into memory just to learn how big it is. The op list already carries the size.
  async function pageImageLongSide(page) {
    let long = 0;
    try {
      const opList = await page.getOperatorList();
      for (let i = 0; i < opList.fnArray.length; i++) {
        const fn = opList.fnArray[i];
        if (fn !== OPS.paintImageXObject && fn !== OPS.paintImageMaskXObject && fn !== OPS.paintInlineImageXObject) continue;
        const a = opList.argsArray[i], arg = a[0];
        for (const v of [Number(arg?.width ?? a[1]), Number(arg?.height ?? a[2])]) if (Number.isFinite(v)) long = Math.max(long, v);
      }
    } catch (_) { /* an op list we can't read just means "render at the cap" */ }
    return long;
  }

  // One page of the GM's all-maps PDF, rasterised whole, for a poster-map Scene.
  //
  // RENDERED, not lifted. Everywhere else this macro lifts the image object out of the page,
  // because the book lays body text OVER its illustrations and lifting is what leaves that
  // text behind. A map page is the opposite case: whatever is on it belongs on the map, and
  // rendering is faithful to a page that turns out to be several layers or to carry vector
  // labels, where lifting the biggest image would silently drop the rest. Same reasoning as
  // the "pagemap" rows (see renderRegion).
  //
  // The DPI comes from the page's OWN artwork rather than a fixed guess: rendering an 11x14
  // page straight to MAP_MAXDIM blows a 300-dpi plate up by half again, which costs megabytes
  // of WebP and adds not one pixel of detail. A page that declares no image size falls back
  // to the cap, which is the resolution the Scene is built at anyway.
  async function renderMapPdfPage(doc, pageNum) {
    const page = await doc.getPage(pageNum);
    try {
      const W = page.view[2] - page.view[0], H = page.view[3] - page.view[1];
      const long = Math.min(CONFIG.MAP_MAXDIM, (await pageImageLongSide(page)) || CONFIG.MAP_MAXDIM);
      return await renderRegion(page, { rect: [0, 0, W, H], dpi: (72 * long) / Math.max(1, W, H) });
    } finally { page.cleanup?.(); }
  }

  // "or a path already in your Foundry data": accept it only if the image loads.
  async function probeMapPath(p) {
    const src = p.replace(/^\/+/, "");
    const dims = await new Promise((res, rej) => {
      const img = new Image();
      img.onload = () => res({ w: img.naturalWidth, h: img.naturalHeight });
      img.onerror = () => rej(new Error(`no image found at "${src}"`));
      img.src = encodeURI(foundry.utils.getRoute(src));
    });
    return { src, ...dims };
  }

  // The poster-map Scene builder lives in the system, and is IMPORTED at the call site in
  // section 7b rather than hand-mirrored like the additive helpers above. The system offers
  // to build these SAME Scenes from these same files on a fresh world
  // (module/hooks/WorldSetup.js), so a drifted copy here would not merely look different:
  // the two would match an existing Scene by different rules, and one would duplicate what
  // the other built instead of refreshing it. Tests import the module, never this script.

  // ---- 5. ensure target directories exist ---------------------------------
  // Creates every missing level, so a custom CONFIG.ROOT works even when its
  // parents don't exist yet. Only "already exists" errors are swallowed.
  async function ensureDir(path) {
    const parts = path.split("/").filter(Boolean);
    for (let i = 1; i <= parts.length; i++) {
      const p = parts.slice(0, i).join("/");
      try { await FP.createDirectory("data", p); }
      catch (e) { if (!/EEXIST|already exists/i.test(e?.message ?? String(e ?? ""))) throw e; }
    }
  }
  // assets/maps is ensured here, not only in the poster-map step below: the pagemap rows
  // upload into it during extraction, which runs whether or not the GM supplies any poster maps.
  if (!CONFIG.DRY_RUN) { await ensureDir(`${CONFIG.ROOT}/assets`); await ensureDir(`${CONFIG.ROOT}/assets/bestiary`); await ensureDir(`${CONFIG.ROOT}/assets/locations`); await ensureDir(`${CONFIG.ROOT}/assets/steading`); await ensureDir(`${CONFIG.ROOT}/assets/treasures`); await ensureDir(`${CONFIG.ROOT}/assets/people`); await ensureDir(`${CONFIG.ROOT}/assets/maps`); await ensureDir(`${CONFIG.ROOT}/assets/diagrams`); }

  // ---- 5a2. where this host actually keeps our files ----------------------
  // A file has two names here and they are not always the same string:
  //
  //   KEY     `${ROOT}/${out}` — what the manifest can predict, and the only thing two
  //           different passes can agree to compare on.
  //   SERVED  what a browse listed it as / what an upload said it stored it at — what a
  //           browser must be pointed at.
  //
  // On a self-hosted Foundry they are identical: the art folder is a plain data path. Where user
  // files live somewhere else they are not. The Forge redirects a `data` upload into its Assets
  // Library and both browse and upload answer with
  // `https://assets.forge-vtt.com/<userId>/${ROOT}/assets/...`, so a run that compared or wired
  // the key alone would skip nothing on a re-import and point every document at a 404.
  //
  // ROOT is the landmark for splitting one into the other because it is the segment both sides
  // always share; `lastIndexOf` so a root that also appears higher up a URL takes the deepest.
  const artKeyOf = (path) => {
    const p = String(path ?? "");
    const marker = `/${CONFIG.ROOT}/`;
    const i = p.lastIndexOf(marker);
    return i >= 0 ? p.slice(i + 1) : p;
  };
  const keyOf = (out) => `${CONFIG.ROOT}/${out}`;
  // key -> served path. Filled from the inventory below and from every upload's own answer.
  const served = new Map();
  const noteServed = (path) => { const k = artKeyOf(path); if (k && !served.has(k)) served.set(k, String(path)); return k; };

  // ---- 5b. inventory what's already on disk (the upgrade path) -------------
  // When the manifest grows in a later release, only the NEW images should pay
  // the extraction cost. Anything already under ROOT is skipped (unless FORCE),
  // and pages whose every image is skipped are never scanned at all.
  const existingFiles = new Set();
  if (artRun && CONFIG.SKIP_EXISTING) {
    // assets/maps also holds the user's poster maps, which are never in `wants` — they just
    // sit in the set unused, so inventorying the whole directory is harmless.
    for (const dir of ["assets/bestiary", "assets/locations", "assets/steading", "assets/treasures", "assets/people", "assets/maps", "assets/diagrams"]) {
      try { for (const f of (await FP.browse("data", `${CONFIG.ROOT}/${dir}`)).files) existingFiles.add(noteServed(decodeURIComponent(f))); }
      catch (_) { /* directory doesn't exist yet -> nothing to skip */ }
    }
  }
  // Effective force: the setup dialog's footer "Force update" tick-box forces a full re-extract
  // of every image (re-parsing the book and overwriting the art already on disk, so the
  // journals pick up the fresh pixels at the same, stable src path). CONFIG.FORCE is the
  // power-user default (true, or a list of out-path substrings) and still applies.
  const FORCE = forceUpdate ? true : CONFIG.FORCE;
  const forced = (out) => FORCE === true || (Array.isArray(FORCE) && FORCE.some((s) => out.includes(s)));

  // ---- 6. extract every wanted image, grouped by page ---------------------
  // Keyed by `out`, because a file can be wanted by more than one row: where the book draws
  // two creatures in one picture (the Adventurer and the Assassin), or a region's plate is
  // also its monster's portrait, the manifest points every one of them at the SAME file. They
  // are still wired independently below - only the pixels are decoded, encoded and uploaded
  // once, instead of once per row under a byte-identical second name.
  const wants = [];
  const wantedOuts = new Set();
  // Wanting nothing is what makes a maps-only run cheap AND quiet: an empty `wants` leaves
  // `pending` and `available` empty, so the extraction loop has nothing to do and section 7's
  // "is it on disk?" gate wires nothing, instead of failing 400 images against a book PDF the
  // GM deliberately didn't supply.
  const want = (w) => { if (!artRun) return; if (!wantedOuts.has(w.out)) { wantedOuts.add(w.out); wants.push(w); } };
  for (const m of monsters) {
    want({ out: m.out, page: m.pdfPage, book: m.book ?? 2, w: m.w, h: m.h, at: m.bbox, nlong: m.nlong });
    // A creature may also carry a hand-framed TOKEN square, extracted as a second, smaller file:
    // that is what its prototype token points at, because a token is a square on a grid and a
    // standing figure fitted into one by `cover` alone loses the creature. It rides the SAME page
    // and image object as the portrait, so it costs no extra decode — the loop simply cuts twice.
    // `portrait` is the want-field for "cut this square last", shared with the people path; a
    // monster has no `crop`, so the square is measured against the whole illustration.
    if (m.token && m.tokenOut) {
      want({ out: m.tokenOut, page: m.pdfPage, book: m.book ?? 2, w: m.w, h: m.h, at: m.bbox, nlong: m.nlong, portrait: m.token });
    }
  }
  for (const s of steadings) want({ out: s.out, page: s.pdfPage, book: s.book ?? 2, w: s.w, h: s.h, at: s.bbox, nlong: s.nlong });
  for (const t of treasures) want({ out: t.out, page: t.pdfPage, book: t.book ?? 2, w: t.w, h: t.h, at: t.bbox, nlong: t.nlong });
  for (const p of people) {
    want({ out: p.out, page: p.pdfPage, book: p.book ?? 2, w: p.w, h: p.h, at: p.bbox, nlong: p.nlong, crop: p.crop });
    // A person may also carry a hand-authored SQUARE face, extracted as a second, smaller file:
    // that is what an actor's img points at, because every place a face shows in play is a small
    // circle and a standing figure cropped by CSS alone loses the head. It rides the SAME page
    // and image object as the portrait, so it costs no extra decode — the loop simply cuts twice.
    if (p.portrait && p.portraitOut) {
      want({ out: p.portraitOut, page: p.pdfPage, book: p.book ?? 2, w: p.w, h: p.h, at: p.bbox, nlong: p.nlong, crop: p.crop, portrait: p.portrait });
    }
  }
  for (const l of locations) for (const im of l.images) want({ out: im.out, page: im.pdfPage, book: im.book ?? l.book ?? 2, w: im.w, h: im.h, at: im.bbox, nlong: im.nlong });
  // A pagemap extracts only if it says HOW (`render`). A row without it is wiring-only: its
  // `out` is another row's file (the village vista is the same PDF image object the
  // "the-village-of-stonetop" location row already extracts), so pushing a want here would
  // decode, encode and upload a byte-identical second copy.
  for (const p of pagemaps) {
    if (!p.render) continue;
    want({ out: p.out, page: p.pdfPage, book: p.book ?? 2, w: p.w, h: p.h, at: p.bbox, nlong: p.nlong,
      mode: p.render, rect: rectFor(p), dpi: p.dpi, mask: p.mask });
  }
  // Diagrams are always rendered — there is nothing on their page to lift — so unlike a pagemap
  // there is no wiring-only case to skip.
  for (const d of diagrams) {
    want({ out: d.out, page: d.pdfPage, book: d.book ?? 2, nlong: d.nlong,
      mode: d.render ?? "region", rect: rectFor(d), dpi: d.dpi, mask: d.mask });
  }
  // `at` used to be a tiebreak between equally-sized candidates, so a row with a sloppy bbox
  // still worked. It is now also the guard on the same-shape fallback, which cannot run without
  // it, so a stencil row missing one silently loses its only recourse on a PDF that re-saved
  // its art. Say so rather than let it look like the picture simply is not in the book.
  for (const w of wants) {
    if ((w.mode ?? "stencil") !== "stencil") continue;
    if (!Array.isArray(w.at) || w.at.length < 2 || !Number.isFinite(w.at[0]) || !Number.isFinite(w.at[1])) {
      log(`${w.out} has no usable placement in the manifest: it can only ever be matched by exact size`);
    }
  }

  // available = images that will actually be on disk after this run; only these
  // get wired into documents (never point a journal or actor at a missing file).
  const available = new Set();
  const pending = [];
  let skipped = 0;
  let unasked = 0;
  // A row out of a book this run has no document for is not a failure — it was never asked for.
  // That is the whole promise of importing one page at a time: the playbook's own Import button
  // submits the playbook and deliberately nothing else, and counting the other 545 rows as
  // failures turned a clean five-image run into a wall of red.
  //
  // Gated on the PDFs that actually LOADED, exactly like `artRun` above, so a file that turned
  // out to be unreadable (or a rulebook refused for being 1-up) degrades the same way: it has
  // already said so once, in a notification naming the file, and does not say it again 400 times
  // in a failure list.
  //
  // Dropped the way an already-on-disk row is, `available` included, so a partial run still WIRES
  // what the world already has: a Book II picture on disk stays pointed at by its journal page
  // whether or not Book II was supplied this time. Without that, importing only the playbook
  // would quietly stop wiring every other picture in the world.
  for (const w of wants) {
    if (!pdfByBook.has(w.book)) { unasked++; if (existingFiles.has(keyOf(w.out))) available.add(w.out); continue; }
    if (CONFIG.SKIP_EXISTING && !forced(w.out) && existingFiles.has(keyOf(w.out))) { skipped++; available.add(w.out); continue; }
    pending.push(w);
  }
  if (unasked) log(`${unasked} image${unasked === 1 ? "" : "s"} come from books not supplied this run; left alone`);
  // Key by book+page so pages from different PDFs never collide (Book I p.142 is
  // a different source than Book II p.142).
  const byPage = new Map();
  for (const w of pending) { const k = w.book + ":" + w.page; if (!byPage.has(k)) byPage.set(k, []); byPage.get(k).push(w); }

  let done = 0, okc = 0, bytes = 0; const failures = [];
  if (artRun) {
    progress.phase("Extracting illustrations...",
      `${pending.length} image${pending.length === 1 ? "" : "s"} from ${byPage.size} page${byPage.size === 1 ? "" : "s"}`
      + (skipped ? ` (${skipped} already on disk)` : "")
      + (forceUpdate ? " (force update: replacing existing art)" : ""));
    progress.step(0);
  }
  const byKeyNum = (k) => k.split(":").map(Number);
  for (const [key, list] of [...byPage.entries()].sort((a, b) => { const A = byKeyNum(a[0]), B = byKeyNum(b[0]); return A[0] - B[0] || A[1] - B[1]; })) {
    const [book, pnum] = byKeyNum(key);
    const doc = pdfByBook.get(book);
    // Defensive only: `pending` is now filtered to the books that loaded, so a row here without a
    // document would mean the two disagreed. It stays a failure rather than a silent skip,
    // because that disagreement is a bug and not a choice the GM made.
    if (!doc) { list.forEach((w) => failures.push(`${w.out} (no ${bookLabel(book)} document for a page that asked for one)`)); done += list.length; progress.step(done / pending.length, `${done}/${pending.length} images`); continue; }
    // One page from a spreads edition, two from a 1-up one — the sheet this row was authored
    // against, however the GM's file happens to store it (see pdfLayout).
    const pnums = sheetPagesFor(book, pnum);
    let sheet;
    try { sheet = await Promise.all(pnums.map((n) => withTimeout(doc.getPage(n), `page ${n} load`))); }
    catch (e) { console.error("[Book II Art] page", pnums.join("+"), e); list.forEach((w) => failures.push(`${w.out} (page ${pnums.join("+")} load failed)`)); done += list.length; progress.step(done / pending.length, `${done}/${pending.length} images`); continue; }
    const page = sheet[0];
    // Only walk the operator list if something on this page actually needs a stencil: a
    // region-only page skips the walk, and a scan failure now fails only the stencil wants
    // instead of every want on the page.
    //
    // The walk stays on the FIRST page of the sheet, which costs nothing today: only the GM
    // playbook is ever read 1-up, and every one of its rows renders a region. A stencil row on a
    // 1-up book would need its placement rebased onto the pair, so say so rather than half-do it.
    let scanned = [];
    let scanErr = null;
    if (list.some((w) => (w.mode ?? "stencil") === "stencil")) {
      if (sheet.length > 1) log(`${bookLabelCap(book)} sheet ${pnum}: stencil rows are matched against page ${pnums[0]} only; a 1-up edition of this book is not supported for those`);
      try { scanned = await withTimeout(scanPage(page), `page ${pnums[0]} scan`); }
      catch (e) { console.error("[Book II Art] page", pnums[0], e); scanErr = e; }
    }
    for (const want of list) {
      try {
        let canvas;
        if ((want.mode ?? "stencil") === "region") {
          canvas = downscale(await withTimeout(renderRegion(sheet, want), `render ${want.out}`), Math.min(CONFIG.PAGEMAP_MAXDIM, want.nlong || CONFIG.PAGEMAP_MAXDIM));
        } else {
          if (scanErr) throw new Error("page scan failed");
          // match by exact native dims, tiebreak by nearest placement (one illustration may serve many targets)
          // A row whose manifest entry has no usable placement can still be matched by size, but it
          // can never use the fallback below, which is only as safe as the placement it checks. Fold
          // that into ONE value here so the tiebreak, the fallback and the failure message cannot
          // disagree about whether this row has somewhere to compare against.
          const at = (Array.isArray(want.at) && Number.isFinite(want.at[0]) && Number.isFinite(want.at[1])) ? want.at : null;
          const offset = (s) => (at ? Math.hypot(s.px - at[0], s.py - at[1]) : 0);
          const nearestFirst = (list) => list.sort((a, b) => offset(a) - offset(b));
          let cands = nearestFirst(scanned.filter((s) => s.w === want.w && s.h === want.h));
          // A printing can re-save an illustration at a different resolution without moving it a
          // hair. The 2nd printing of both books does exactly that to nine pictures, storing them
          // at twice the pixels this manifest recorded, and a match on pixel size alone simply
          // cannot see them: the row fails and the GM gets a broken image on a bestiary entry.
          //
          // What identifies a picture across printings is its SHAPE and its PLACE on the page.
          // The pixel count is only how one export happened to store it, which is why it is the
          // thing that changed. So when the recorded size is absent, take the illustration with
          // the same proportions sitting where this row says its art sits, and let the
          // normalisation below put it back at the recorded size.
          //
          // This is a FALLBACK and never a replacement: an exact hit always wins, so a PDF that
          // still carries the recorded size is matched precisely as before. Never smaller than
          // the recorded size, both because the lift is only ever scaled DOWN to it and because
          // that is what stops a page's own furniture (a 75x75 bullet, a 651x13 rule) from ever
          // standing in for its plate.
          if (!cands.length && at) {
            const shape = want.w / want.h;
            cands = nearestFirst(scanned.filter((s) => s.w >= want.w && s.h >= want.h
              && Math.abs((s.w / s.h) / shape - 1) <= CONFIG.SHAPE_TOL
              && offset(s) <= CONFIG.MAX_OFFSET_PT));
          }
          if (!cands.length) {
            // Every distinct size the page actually carries, so a mismatch says what the art has
            // become instead of only that nothing fitted. Deduped and capped: a page paints the
            // same object many times, and a scan of a busy spread is otherwise a wall.
            const dims = [...new Set(scanned.map((s) => `${s.w}x${s.h}${s.isMask ? " (mask)" : ""}`))];
            log(`no match for ${want.out}: wanted ${want.w}x${want.h}`
              + (at ? ` (or the same shape near ${at[0]},${at[1]})` : " (exact size only: this row has no placement)")
              + ` on p${pnum}; the page carries ` + (dims.slice(0, 12).join(", ") || "(nothing)")
              + (dims.length > 12 ? `, +${dims.length - 12} more` : ""));
            throw new Error(`no ${want.w}x${want.h} on p${pnum}`);
          }
          const s = cands[0];
          const obj = s.obj ?? await withTimeout(resolveObj(s.page, s.key), `resolve ${want.out} (p${pnum} ${s.key})`);
          if (!obj?.data) throw new Error("unresolved image data");
          let lifted = imageToCanvas(obj, s.isMask);
          // Normalise to the resolution `crop` and `portrait` were measured against. A no-op when
          // the match was exact, because then the lift's long side already IS this cap, so there
          // is one path through here rather than two: whichever printing supplied the pixels, the
          // crop fractions land where the picker drew them and the file on disk comes out the
          // size every other conversion produces. The target is the MANIFEST's size and not a
          // ratio off the lifted canvas, so it lands there exactly rather than near it.
          lifted = swap(lifted, downscale(lifted, Math.max(want.w, want.h)));
          // A person row may carve one portrait out of a multi-figure illustration: crop the
          // lifted stencil (fractions of it) before the resolution cap. Every other row leaves
          // `want.crop` undefined and takes the whole illustration as before.
          if (want.crop) lifted = swap(lifted, cropCanvas(lifted, want.crop));
          // The square is measured against the PERSON image, i.e. against what `crop` just cut,
          // so applying the two in sequence IS the composition — there is no combined rect to
          // compute and get subtly wrong. Same coordinate space the in-Foundry rebuild uses when
          // it cuts this square straight out of the person file on disk.
          if (want.portrait) lifted = swap(lifted, cropCanvas(lifted, want.portrait));
          // Free the native-size backing store as we go (some are 30+ MB, e.g. 3309x2315). When
          // downscale returned a smaller copy, the original is dead weight until GC; zero its
          // dimensions to release the pixel buffer immediately instead of letting them pile up.
          // `swap` above does exactly this for each earlier link in the chain.
          canvas = swap(lifted, downscale(lifted, Math.min(CONFIG.MAXDIM, want.nlong || CONFIG.MAXDIM)));
        }
        const blob = await withTimeout(toBlob(canvas), `encode ${want.out}`);
        if (!blob) throw new Error("empty blob");
        bytes += blob.size;
        if (!CONFIG.DRY_RUN) {
          const dir = `${CONFIG.ROOT}/${want.out.slice(0, want.out.lastIndexOf("/"))}`;
          const name = want.out.slice(want.out.lastIndexOf("/") + 1);
          // A REJECTED upload does not throw. Foundry's own FilePicker returns false when the
          // server answers with an error and undefined when it answers without a path; The Forge's
          // replacement returns false on every failure path it has. Taking that as success is how a
          // run reports "497 ok, 0 failed" having saved none of them, wires every document to a file
          // that was never written, and leaves the GM with no signal but a console line. So the
          // falsy result becomes the failure it is, and is listed with the rest.
          const res = await withTimeout(FP.upload("data", dir, new File([blob], name, { type: "image/webp" }), { overwrite: true }, { notify: false }), `upload ${want.out}`);
          if (!res) throw new Error("the server rejected the upload");
          // Believe the upload about where it put the file, rather than reassembling the path.
          if (typeof res.path === "string" && res.path) noteServed(res.path);
          available.add(want.out);
        }
        canvas.width = canvas.height = 0; // release the working canvas's pixel buffer promptly
        okc++;
      } catch (e) { console.error("[Book II Art] failed:", want.out, e); failures.push(`${want.out} (${e.message})`); }
      done++;
      progress.step(done / pending.length, `${done}/${pending.length} images`);
      if (done % 20 === 0) log(done + "/" + pending.length);
    }
    // Release everything pdf.js cached for this page before moving on: the parsed operator
    // list and — the memory killer — every lifted stencil's raw pixel array, which otherwise
    // lives in page.objs for the ENTIRE run. Across 200+ large Book pages that retention grows
    // into gigabytes and stalls extraction mid-run (the "freezes around page 235" failure this
    // fixes). Cleaning each page as we finish keeps memory flat. Best-effort; never fail on it.
    try { page.cleanup(); } catch (_) {}
  }
  log(`images: ${okc} ok, ${skipped} skipped (already present), ${failures.length} failed, ${(bytes / 1e6).toFixed(1)} MB`);
  if (CONFIG.DRY_RUN) { await progress.close(); return notify.info(`Book II Art (dry run): matched ${okc}/${pending.length} missing images`
    + (skipped ? `, ${skipped} already present` : "") + `, ${failures.length} failures. Nothing saved.`); }

  // ---- 7. wire images into the compendia ----------------------------------
  // Every write below is gated on `available` — the images this run put (or found) on disk —
  // so a maps-only run, whose `available` is empty by construction, already writes nothing.
  // The `artRun` guards here are about the WORK rather than the writes: without them the run
  // would still unlock two packs and read a hundred-odd compendium documents to decide to do
  // nothing, under a progress line claiming to update them.
  if (artRun) progress.phase("Updating compendium documents...");
  const besPack = game.packs.get(monsters[0]?.actorPack ?? "stonetop-pwd.stonetop-bestiary");
  const jrnPack = game.packs.get("stonetop-pwd.stonetop-journal");
  const relock = [];
  if (artRun) for (const p of [besPack, jrnPack]) if (p?.locked) { await p.configure({ locked: false }); relock.push(p); }

  // Where a browser fetches this picture from — the served path when we learned one, else the key.
  // Every wiring site below uses this; the two identity checks that remain use `keyOf` directly.
  const srcOf = (out) => served.get(keyOf(out)) ?? keyOf(out);
  // Minimal update that points an actor's portrait (and, unless disabled, its
  // prototype token) at `src`. Returns null when nothing changed so we skip
  // no-op writes and don't inflate the counters. Setting the token src is what
  // makes newly-dropped tokens use the illustration; TOKEN_FIT controls whether
  // the wide art fills the token square or letterboxes inside it.
  // `tokenSrc` defaults to `src`, which is what everything but a hand-framed creature wants: one
  // picture doing both jobs. A creature with a token square passes its own smaller file, so the
  // token is the square while `img` stays the whole illustration — which is what the sheet, the
  // codex page and an image-hover popup all read.
  const artUpdate = (doc, src, tokenSrc = src) => {
    const upd = {};
    if (doc.img !== src) upd.img = src;
    if (CONFIG.UPDATE_TOKEN_ART) {
      const tex = doc.prototypeToken?.texture;
      if (tex?.src !== tokenSrc) upd["prototypeToken.texture.src"] = tokenSrc;
      if (CONFIG.TOKEN_FIT && tex?.fit !== CONFIG.TOKEN_FIT) upd["prototypeToken.texture.fit"] = CONFIG.TOKEN_FIT;
    }
    return Object.keys(upd).length ? upd : null;
  };
  // The picture this creature's TOKEN should show: its hand-framed square when the manifest names
  // one AND that file actually landed, else the whole illustration. Gated on `available` like
  // every other wiring decision here — never point a token at a file this run failed to write.
  const tokenSrcOf = (m, src) => (m.tokenOut && available.has(m.tokenOut) ? srcOf(m.tokenOut) : src);

  // The steading portrait is only adopted when the "Stonetop" sheet still shows a shipped
  // placeholder (the "S" emblem, an older default image, or a Foundry default); never a
  // portrait the group chose themselves. Mirrors the self-heal set in
  // module/hooks/StonetopSingleton.js so the two stay in agreement.
  const STEADING_PLACEHOLDER_IMGS = new Set([
    "systems/stonetop-pwd/assets/stonetop_image.svg", "/systems/stonetop-pwd/assets/stonetop_image.svg",
    "systems/stonetop-pwd/assets/stonetop_image.webp", "/systems/stonetop-pwd/assets/stonetop_image.webp",
    "systems/stonetop-pwd/assets/stonetop_image.png", "/systems/stonetop-pwd/assets/stonetop_image.png",
    "systems/stonetop/assets/stonetop_image.webp", "/systems/stonetop/assets/stonetop_image.webp",
    "systems/stonetop/assets/stonetop_image.png", "/systems/stonetop/assets/stonetop_image.png",
  ]);
  const DEFAULT_TOKEN_IMG = globalThis.CONST?.DEFAULT_TOKEN ?? "icons/svg/mystery-man.svg";
  const isSteadingPlaceholder = (img) => !img
    || img === "icons/svg/mystery-man.svg" || img === "icons/svg/item-bag.svg"
    || img === DEFAULT_TOKEN_IMG || STEADING_PLACEHOLDER_IMGS.has(img);

  // ---- world-journal helpers (mirror module/book2-art/world-journal-art.js) ---------
  // The art must land in the world journals the GM actually reads (the gazetteer +
  // bestiary codex seeded into the sidebar), not just the compendium.
  //
  // These are HAND-MIRRORS of the system's shared helper, because this script has to stay a
  // single pasteable file. They must stay behaviourally identical to it, or a later runtime
  // re-apply double-adds what the macro placed. That is not theoretical: locSectionsWithArt
  // below matched art by its WRAPPER markup long after the module had moved to matching by
  // `src` (the module's own comment explains why), which duplicated a location's art on any
  // world where a GM had re-saved the page through ProseMirror. If you change either helper,
  // change both. Anything with a strip step is imported instead (see the codex pass below):
  // hand-mirroring a strip is what turns drift into duplicated or orphaned images.
  const artEmbed = (src, name) => `<p><img class="stonetop-journal-art" src="${src}" alt="${esc(name)}"></p>`;
  const besDescWithArt = (description, src, name) => {
    const desc = description ?? "";
    return desc.includes(src) ? null : artEmbed(src, name) + desc;
  };
  const leadArtSection = (body) => ({ kind: "prose", heading: "", group: "glance", danger: false, body, pairs: [], groups: [] });
  // Authoritative section placement (mirrors module/book2-art/world-journal-art.js): the
  // manifest decides WHICH section each illustration lives in, so an embed found in another
  // section is relocated here (not skipped as "already present"). A re-sectioning in the
  // picker therefore actually moves the image; an already-correct page is a no-op (null).
  const locSectionsWithArt = (sections, sectionIndex, srcs, name) => {
    const list = Array.isArray(sections) ? sections : [];
    const wanted = [];
    for (const s of srcs ?? []) if (s && !wanted.includes(s)) wanted.push(s);
    if (!wanted.length) return null;
    // Detection + stripping key on the exact src="<path>", NOT the wrapper markup — the same
    // rule stripManagedMap below already follows. A GM who opens a location page re-saves its
    // sections through ProseMirror, which normalizes each <img> (reorders attributes, and can
    // drop our class), so a wrapper-shaped match would stop recognizing art it had already
    // placed: it would re-add a duplicate on the next run AND fail to strip the old copy when
    // relocating. Quote-delimited so one path is never a prefix of another.
    const rx = (s) => String(s).replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
    const imgForSrc = (src) => new RegExp(`<img\\b[^>]*\\ssrc="${rx(src)}"[^>]*>`, "gi");
    const hasSrc = (body, src) => imgForSrc(src).test(String(body ?? ""));
    const stripSrc = (body, src) => String(body ?? "")
      .replace(new RegExp(`<p\\b[^>]*>\\s*<img\\b[^>]*\\ssrc="${rx(src)}"[^>]*>\\s*</p>`, "gi"), "")
      .replace(imgForSrc(src), "");
    // Insertion point ONLY: the last canonical embed we wrote, so new art keeps book order.
    // Fresh global regex each call: its lastIndex must not leak.
    const embRe = () => /<p><img class="stonetop-journal-art"[^>]*><\/p>/g;
    // Target the manifest's section; fall back to the first real section if it's gone.
    const requested = sectionIndex ?? 0;
    const targetIdx = list[requested] ? requested : list.findIndex((s) => s);
    // No-op fast path: every wanted src already sits in the target section and nowhere else.
    const targetBody = targetIdx >= 0 ? (list[targetIdx].body ?? "") : "";
    let needsWork = wanted.some((src) => !hasSrc(targetBody, src));
    for (let i = 0; i < list.length && !needsWork; i++) { if (i === targetIdx || !list[i]) continue; needsWork = wanted.some((src) => hasSrc(list[i].body ?? "", src)); }
    if (!needsWork) return null;
    // Strip each wanted src from every section, then re-add them to the target section.
    const next = list.slice();
    for (let i = 0; i < next.length; i++) { const sec = next[i]; if (!sec) continue; let body = sec.body ?? ""; for (const src of wanted) body = stripSrc(body, src); if (body !== (sec.body ?? "")) next[i] = { ...sec, body }; }
    const add = wanted.map((src) => artEmbed(src, name)).join("");
    if (targetIdx < 0) return [leadArtSection(add)];
    const sec = next[targetIdx];
    const body = sec.body ?? "";
    const artRe = embRe();
    let lastEnd = -1, mt; while ((mt = artRe.exec(body))) lastEnd = mt.index + mt[0].length;
    next[targetIdx] = { ...sec, body: lastEnd >= 0 ? body.slice(0, lastEnd) + add + body.slice(lastEnd) : add + body };
    return next;
  };
  // A Setting Overview regional map: a captioned figure prepended to a plain text page's
  // text.content. Distinct markup + class from the illustrations above; idempotent on the
  // src AND a no-op if the page already carries any map figure (a GM's own labelled map is
  // never stacked with a second one). Mirrors module/book2-art/world-journal-art.js.
  const mapFigureEmbed = (src, name) => `<figure class="stonetop-map"><img src="${src}" alt="${esc(name)}"></figure>`;
  // Strip a map we previously wrote for this exact src — as a <figure>, or (if ProseMirror
  // unwrapped it when a GM saved the page) a bare <img> / its sole-content <p>. Keyed on the
  // src path, never the wrapper markup or our class, both of which ProseMirror rewrites.
  const stripManagedMap = (html, src) => {
    const s = String(src).replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
    return String(html ?? "")
      .replace(new RegExp(`<figure\\b[^>]*>(?:(?!</figure>)[\\s\\S])*?<img\\b[^>]*\\ssrc="${s}"[^>]*>(?:(?!</figure>)[\\s\\S])*?</figure>`, "gi"), "")
      .replace(new RegExp(`<p\\b[^>]*>\\s*<img\\b[^>]*\\ssrc="${s}"[^>]*>\\s*</p>`, "gi"), "")
      .replace(new RegExp(`<img\\b[^>]*\\ssrc="${s}"[^>]*>`, "gi"), "");
  };
  // New text-page content showing THIS map, replacing a map we previously wrote (any src in
  // `replaceSrcs`). Strips ours BEFORE the any-map check, so our own superseded map can't
  // block its replacement while a `stonetop-map` figure we don't recognise (a GM's own
  // labelled variant) still does. Mirrors module/book2-art/world-journal-art.js byte for
  // byte — that is what stops the runtime re-apply from double-adding what this wrote.
  const textPageWithManagedMap = (content, src, name, replaceSrcs = []) => {
    let html = String(content ?? "");
    if (html.includes(src)) return null;
    for (const old of replaceSrcs ?? []) if (old && old !== src) html = stripManagedMap(html, old);
    if (html.includes('class="stonetop-map"')) return null;
    return mapFigureEmbed(src, name) + html;
  };
  // Match a world page to a compendium page by id first (stable on a fresh seed) then by
  // name+type (the managed-journal refresh recreates pages with fresh ids).
  const matchWorldPage = (pages, pageId, pageName, pageType) => {
    const list = Array.isArray(pages) ? pages : (pages?.contents ?? (pages ? Array.from(pages) : []));
    return list.find((p) => (p.id ?? p._id) === pageId)
      ?? (pageName ? list.find((p) => p.name === pageName && p.type === pageType) : null) ?? null;
  };

  // World journals seeded from our compendiums, indexed by the compendium source uuid
  // core stamps on import. Empty when the sync is off or nothing has been seeded.
  const worldBySource = new Map();
  if (artRun && CONFIG.SYNC_WORLD_JOURNALS) {
    for (const j of game.journal ?? []) {
      const s = j._stats?.compendiumSource ?? j.getFlag?.("core", "sourceId");
      if (!s || !s.startsWith("Compendium.stonetop-pwd.")) continue;
      if (!worldBySource.has(s)) worldBySource.set(s, []);
      worldBySource.get(s).push(j);
    }
  }
  const jrnSource = (entryId) => `Compendium.stonetop-pwd.stonetop-journal.JournalEntry.${entryId}`;
  // Best-effort: the system's content-fingerprint helper, so a world journal we add art
  // to can be re-stamped as "pristine" and keep receiving future prose updates from the
  // managed-journal channel. If it can't be loaded (older/renamed system), the art is
  // still applied; only the auto-refresh of that entry's prose is forgone.
  let managedHash = null;
  if (artRun && CONFIG.SYNC_WORLD_JOURNALS) {
    try {
      const route = foundry.utils?.getRoute?.("systems/stonetop-pwd/module/hooks/journal-sync-core.js")
        ?? "/systems/stonetop-pwd/module/hooks/journal-sync-core.js";
      ({ managedHash } = await import(route));
    } catch (_) { managedHash = null; }
  }
  // The curated-codex helper is IMPORTED, never hand-mirrored like the additive helpers
  // above. It has a strip step, so a drifted copy would not merely miss an embed — it would
  // duplicate art or orphan it on the page, and no test could catch it (tests/book2-art
  // imports the module, never this script). If the import fails we skip the codex pass and
  // say so: an uncurated page is a known, harmless state; a silently duplicated one is not.
  let codexFieldWithArt = null;
  if (artRun && codex.length) {
    try {
      const route = foundry.utils?.getRoute?.("systems/stonetop-pwd/module/book2-art/world-journal-art.js")
        ?? "/systems/stonetop-pwd/module/book2-art/world-journal-art.js";
      ({ codexFieldWithArt } = await import(route));
    } catch (_) { codexFieldWithArt = null; }
    if (!codexFieldWithArt) notify.warn("Book II Art: this system build can't curate codex pages, so shared pages keep every creature's art. Update the system and re-run to apply your picks.");
  }
  // Per-entry pre-injection pristine state, captured the FIRST time we touch an entry.
  const touchedEntries = new Map();
  const noteEntry = (entry) => {
    if (touchedEntries.has(entry)) return;
    const base = entry.getFlag?.("stonetop-pwd", "journalSync");
    let pristine = false;
    try { pristine = !!managedHash && !!base?.hash && base.hash === managedHash(entry.toObject()); } catch (_) { /* treat as edited */ }
    touchedEntries.set(entry, { base, pristine });
  };

  let actorsUpdated = 0, besPages = 0, locPages = 0, worldActors = 0, worldJournalPages = 0, steadingUpdated = 0, treasureArt = 0, peopleArt = 0, peopleSquares = 0, soPages = 0, diagramArt = 0;
  try {
    for (const m of monsters) {
      if (!available.has(m.out)) continue; // never wire art that isn't on disk (failed or missing extraction)
      const src = srcOf(m.out);
      try { const actor = await besPack.getDocument(m.actorId); const upd = actor && artUpdate(actor, src, tokenSrcOf(m, src)); if (upd) { await actor.update(upd); actorsUpdated++; } }
      catch (e) { console.error("[Book II Art] actor", m.slug, e); }
      // The journal half only — the portrait/token above is per-actor and always applies. A
      // curated page belongs to the codex pass below; several creatures can share one codex
      // page, and this is what stops their portraits stacking on it.
      if (m.journalEntryId && m.journalPageId && !(curated.has(m.journalEntryId) && codexFieldWithArt)) {
        try {
          const page = (await jrnPack.getDocument(m.journalEntryId))?.pages?.get(m.journalPageId);
          if (page) {
            const nd = besDescWithArt(page.system?.description, src, m.name);
            if (nd != null) { await page.update({ "system.description": nd }); besPages++; }
            if (CONFIG.SYNC_WORLD_JOURNALS) for (const entry of worldBySource.get(jrnSource(m.journalEntryId)) ?? []) {
              const wp = matchWorldPage(entry.pages, page.id, page.name, page.type);
              if (!wp) continue;
              const wnd = besDescWithArt(wp.system?.description, src, m.name);
              if (wnd != null) { noteEntry(entry); await wp.update({ "system.description": wnd }); worldJournalPages++; }
            }
          }
        } catch (e) { console.error("[Book II Art] bestiary journal", m.slug, e); }
      }
    }
    // Curated codex pages: the manifest decides which of a shared page's illustrations show
    // and under which heading, so art the user hid is stripped rather than merely not
    // re-added. Skipped entirely when the helper couldn't be imported (warned above).
    if (codexFieldWithArt) for (const c of codex) {
      // Nothing of this page's art on disk: this GM never imported it, so leave the page
      // alone rather than stripping art they do have.
      if (!(c.managed ?? []).some((out) => available.has(out))) continue;
      try {
        // `slots` filtered to what's on disk so a partial import never embeds a broken <img>;
        // `managed` stays complete so a missing file can still be stripped off the page.
        const curation = {
          managed: (c.managed ?? []).map(srcOf),
          slots: (c.slots ?? []).map((s) => ({
            slot: s.slot,
            images: (s.images ?? []).filter((i) => available.has(i.out)).map((i) => ({ src: srcOf(i.out), name: i.name })),
          })),
        };
        const page = (await jrnPack.getDocument(c.journalEntryId))?.pages?.get(c.journalPageId);
        if (!page) continue;
        const upd = {};
        const nd = codexFieldWithArt(page.system?.description, "description", curation);
        if (nd != null) upd["system.description"] = nd;
        const nn = codexFieldWithArt(page.system?.nests, "nests", curation);
        if (nn != null) upd["system.nests"] = nn;
        if (Object.keys(upd).length) { await page.update(upd); besPages++; }
        if (CONFIG.SYNC_WORLD_JOURNALS) for (const entry of worldBySource.get(jrnSource(c.journalEntryId)) ?? []) {
          const wp = matchWorldPage(entry.pages, page.id, page.name, page.type);
          if (!wp) continue;
          const wupd = {};
          const wnd = codexFieldWithArt(wp.system?.description, "description", curation);
          if (wnd != null) wupd["system.description"] = wnd;
          const wnn = codexFieldWithArt(wp.system?.nests, "nests", curation);
          if (wnn != null) wupd["system.nests"] = wnn;
          // noteEntry BEFORE the write: hiding art is a removal, and a removal that skipped
          // this would flip a pristine entry to "GM-edited" and permanently opt it out of
          // future prose updates.
          if (Object.keys(wupd).length) { noteEntry(entry); await wp.update(wupd); worldJournalPages++; }
        }
      } catch (e) { console.error("[Book II Art] curated codex page", c.name ?? c.journalEntryId, e); }
    }
    // Guarded as a whole (unlike the loops above, which skip on `available` before touching the
    // pack) because this one loads the page BEFORE it learns it has no art to place.
    if (artRun) for (const l of locations) {
      try {
        const page = (await jrnPack.getDocument(l.journalEntryId))?.pages?.get(l.journalPageId);
        if (!page) continue;
        const srcs = l.images.filter((im) => available.has(im.out)).map((im) => srcOf(im.out));
        const cns = locSectionsWithArt(page.system?.sections, l.sectionIndex, srcs, l.name);
        if (cns) { await page.update({ "system.sections": cns }); locPages++; }
        if (CONFIG.SYNC_WORLD_JOURNALS) for (const entry of worldBySource.get(jrnSource(l.journalEntryId)) ?? []) {
          const wp = matchWorldPage(entry.pages, page.id, page.name, page.type);
          if (!wp) continue;
          const wns = locSectionsWithArt(wp.system?.sections, l.sectionIndex, srcs, l.name);
          if (wns) { noteEntry(entry); await wp.update({ "system.sections": wns }); worldJournalPages++; }
        }
      } catch (e) { console.error("[Book II Art] location", l.slug, e); }
    }
    // The steading portrait (the "Stonetop" sheet). Its actor is created at runtime with
    // no stable compendium id, so find the world singleton by type; only adopt the book
    // art over a shipped placeholder, leaving a custom portrait the group set untouched.
    // It's a durable world actor pointing at the durable ROOT, so it needs no runtime
    // re-apply after a system update the way the compendium documents do.
    for (const s of steadings) {
      if (!available.has(s.out)) continue;
      try {
        const actor = game.actors?.find((a) => a.type === "stonetop");
        if (!actor || !isSteadingPlaceholder(actor.img)) continue;
        const upd = artUpdate(actor, srcOf(s.out));
        if (upd) { await actor.update(upd); steadingUpdated++; }
      } catch (e) { console.error("[Book II Art] steading", s.slug, e); }
    }
    // The Setting Overview's map/vista pages: plain text pages that get the printed Book II
    // art prepended as a figure. Runs inside section 7 so it shares the jrnPack unlock and
    // the re-stamp loop below.
    //
    // Each row carries an ORDERED preference (`pageChain`): the GM playbook's 300 dpi map first
    // where there is one, then the Book II crop, then the user-supplied poster map an earlier
    // release embedded here. We show the best one that is actually on disk and supersede the
    // rest, so a GM who has only Book II keeps the Book II crop and one who has neither keeps the
    // poster map they already had, rather than being left with a blank page. The poster map file
    // itself is never touched: it still backs its Scene, which is why the two consumers
    // deliberately read different files.
    //
    // Rows that own no page are skipped: the GM playbook's three maps are extraction-only, and
    // asking the pack for `undefined` would be one thrown error per row per run.
    // Also whole-loop guarded: its pick can come from `existingFiles` rather than `available`,
    // so on a maps-only run it would otherwise re-embed art that is already on those pages.
    if (artRun) for (const p of pagemaps) {
      if (!p.soEntryId || !p.soPageId) continue;
      const chain = pageChain(p);
      const pick = chain.find((o) => available.has(o) || existingFiles.has(keyOf(o)));
      if (!pick) continue;
      const src = srcOf(pick);
      const replaces = chain.filter((o) => o !== pick).map(srcOf);
      try {
        const page = (await jrnPack.getDocument(p.soEntryId))?.pages?.get(p.soPageId);
        if (!page) continue;
        const nd = textPageWithManagedMap(page.text?.content, src, p.name, replaces);
        if (nd != null) { await page.update({ "text.content": nd }); soPages++; }
        if (CONFIG.SYNC_WORLD_JOURNALS) for (const entry of worldBySource.get(jrnSource(p.soEntryId)) ?? []) {
          const wp = matchWorldPage(entry.pages, page.id, page.name, page.type);
          if (!wp) continue;
          const wnd = textPageWithManagedMap(wp.text?.content, src, p.name, replaces);
          if (wnd != null) { noteEntry(entry); await wp.update({ "text.content": wnd }); worldJournalPages++; }
        }
      } catch (e) { console.error("[Book II Art] pagemap", p.slug, e); }
    }
    // Where this host serves our art folder from, published BEFORE the two indexes below —
    // they are keyed by the manifest's own `out` paths, and every consumer of them (the People
    // gallery, the treasure drop) resolves through this to get something a browser can fetch.
    // Empty on a self-hosted Foundry, so it changes nothing there. See art-root.js.
    if (artRun) {
      try {
        if (game.settings.settings?.has?.("stonetop-pwd.book2ArtPrefix")) {
          // Whatever sits in front of `${ROOT}/...` in a path the host itself gave us: the
          // difference between one file's served path and its key. Taken from a real answer
          // rather than assembled, and left alone when we learned nothing this run (a maps-only
          // pass, or a re-import where everything was skipped and no directory listed).
          let prefix = null;
          for (const [key, path] of served) {
            if (path.endsWith(key)) { prefix = path.slice(0, path.length - key.length); break; }
          }
          if (prefix !== null && game.settings.get("stonetop-pwd", "book2ArtPrefix") !== prefix) {
            await game.settings.set("stonetop-pwd", "book2ArtPrefix", prefix);
          }
        }
      } catch (e) { console.error("[Book II Art] art prefix", e); }
    }
    // Treasure art. Nothing to update: a treasure is built as an Item only when a player
    // drags its line off the journal, so instead of writing documents we publish WHICH
    // treasure images are now on disk. treasure-drops.js reads this world setting when it
    // builds the drop, and so never points an item at a file this world doesn't have.
    // Publish one document-less art index: { key -> value } for the rows whose file this run
    // can see on disk, UNIONED with whatever the world already had.
    //
    // Four indexes are published this way and each wants the same four rules, so they are
    // stated once here rather than four times below: skip silently in a world that never
    // registered the setting; union rather than replace, so a DELTA run that re-extracted
    // nothing does not empty an index an earlier full run built; write only on an actual
    // change, since every write costs a socket broadcast and busts the art browse cache; and
    // never let one index's failure take the rest of the run down with it.
    //
    // `pair(row)` returns the [key, value] to record, or something falsy for a row whose file
    // is not there -- which is also where the per-index availability rule lives, since the
    // squares check a different path from the illustration they belong to. Same shape as
    // refreshArtIndex on the module side.
    const publishIndex = async (key, rows, pair, label) => {
      try {
        if (!game.settings.settings?.has?.("stonetop-pwd." + key)) return 0;
        const prev = game.settings.get("stonetop-pwd", key);
        const merged = { ...(prev && typeof prev === "object" && !Array.isArray(prev) ? prev : {}) };
        for (const row of rows) { const entry = pair(row); if (entry) merged[entry[0]] = entry[1]; }
        if (JSON.stringify(merged) !== JSON.stringify(prev)) await game.settings.set("stonetop-pwd", key, merged);
        return Object.keys(merged).length;
      } catch (e) { console.error("[Book II Art] " + label + " index", e); return 0; }
    };
    // Every index records the manifest's own `out` path, which is what the consuming module
    // resolves against the art folder -- it never re-derives the path from the slug, so the
    // two sides cannot drift apart.
    if (artRun && treasures.length) {
      treasureArt = await publishIndex("treasureArt", treasures,
        (t) => available.has(t.out) && [t.slug, t.out], "treasure");
    }
    // The GM playbook's flowcharts. Document-less for the same reason a treasure is: nothing in
    // any compendium points at them, so publishing WHICH are on disk is the whole apply step, and
    // the GM Toolkit sheet's Core Loop tab reads the index to decide between showing a diagram and
    // showing the "run Import Book Art" hint. Union with the prior index, like the others, so a
    // delta run that re-extracted neither does not empty the tab.
    if (artRun && diagrams.length) {
      diagramArt = await publishIndex("gmDiagramArt", diagrams,
        (d) => available.has(d.out) && [d.slug, d.out], "GM diagram");
    }
    // People art. Also document-less: the steading sheet's portrait gallery reads this world
    // setting to know which "People of Stonetop" illustrations are on disk, and what to label
    // each one. Map is { manifest out path -> display name }; union with the prior index so a
    // delta run never forgets a person it didn't re-extract this time.
    if (artRun && people.length) {
      peopleArt = await publishIndex("peopleArt", people,
        (p) => available.has(p.out) && [p.out, p.name], "people");
      // The square faces, indexed illustration -> square, so the gallery and the sheets can
      // hand out a face rather than a whole standing figure. Separate index because `peopleArt`
      // is `{ out -> name }` in every world that already has one; consumers join the two by
      // `out`, so this is purely additive and nothing has to migrate.
      peopleSquares = await publishIndex("peoplePortraitArt", people,
        (p) => p.portraitOut && available.has(p.portraitOut) && [p.out, p.portraitOut], "people square");
    }
    if (CONFIG.SYNC_WORLD_ACTORS) {
      for (const m of monsters) {
        if (!available.has(m.out)) continue;
        const uuid = `Compendium.${m.actorPack}.Actor.${m.actorId}`, src = srcOf(m.out);
        const tokSrc = tokenSrcOf(m, src);
        for (const a of game.actors.filter((a) => a._stats?.compendiumSource === uuid || a.getFlag?.("core", "sourceId") === uuid)) { const upd = artUpdate(a, src, tokSrc); if (upd) { await a.update(upd); worldActors++; } }
      }
    }
    // Keep the managed-journal channel's baseline in sync for the world journals we added
    // art to: a still-pristine entry is re-stamped so the channel keeps treating it as
    // pristine (and keeps delivering future prose); edited entries keep their edited signal.
    if (CONFIG.SYNC_WORLD_JOURNALS && managedHash) {
      for (const [entry, { base, pristine }] of touchedEntries) {
        if (!pristine) continue;
        try { await entry.setFlag("stonetop-pwd", "journalSync", { hash: managedHash(entry.toObject()), version: base?.version ?? game.system.version }); }
        catch (e) { console.error("[Book II Art] journal re-stamp", entry?.name, e); }
      }
    }
  } finally { if (CONFIG.RELOCK_PACKS) for (const p of relock) { try { await p.configure({ locked: true }); } catch (_) {} } }

  // ---- 7b. poster maps -> scenes ------------------------------------------
  // Scenes only. The Setting Overview's map pages are no longer fed from here: they show
  // the printed, labelled Book II maps this run rendered out of the PDF ("pagemap" rows,
  // wired in section 7), while the GM's own poster maps stay the Scene backdrops. The two
  // consumers deliberately read different files.
  let scenesCreated = 0, scenesUpdated = 0, pinsPlaced = 0;

  // When the GM has the single all-maps PDF rather than five image files, this is the
  // document every pick is rendered out of. Normally the setup dialog has already parsed it
  // (that is where the per-row page previews came from), so this reuses that copy instead of
  // reading a ~40MB file twice; it only re-parses if the dialog's read failed or was still in
  // flight. A PDF that cannot be read at all costs the maps and nothing else: the art import
  // above has already landed by this point.
  let mapsPdfDoc = null;
  if (mapPicks.length && mapChoice.source === "pdf") {
    if (mapsPdf.doc && mapsPdf.file === mapChoice.pdfFile) mapsPdfDoc = mapsPdf.doc;
    else {
      progress.phase("Reading your maps PDF...", mapChoice.pdfFile?.name ?? "");
      try {
        mapsPdfDoc = await pdfjs.getDocument({ data: await mapChoice.pdfFile.arrayBuffer(), isEvalSupported: false }).promise;
      } catch (e) {
        console.error("[Book II Art] all-maps PDF", e);
        notify.error("Import Book Art: your all-maps PDF could not be read, so the poster maps were skipped.");
        failures.push(`maps PDF (${e.message})`);
      }
    }
  }
  // Nothing to build if the maps were to come out of a PDF we could not open.
  const mapRuns = mapChoice.source === "pdf" && !mapsPdfDoc ? [] : mapPicks;

  // Only the SCENE step depends on this import; the upload below does not. So a system build
  // too old to provide it still saves the GM's maps to disk, and Stonetop's own once-per-world
  // offer builds their Scenes from those very files on the next world load. Losing the import
  // costs a convenience, never the import itself.
  let upsertPosterMapScene = null;
  if (mapRuns.length) {
    try {
      const route = foundry.utils?.getRoute?.("systems/stonetop-pwd/module/book2-art/poster-maps.js")
        ?? "/systems/stonetop-pwd/module/book2-art/poster-maps.js";
      ({ upsertPosterMapScene } = await import(route));
    } catch (_) { upsertPosterMapScene = null; }
    if (!upsertPosterMapScene) notify.warn("Book II Art: your poster maps will be saved, but this system build can't build their Scenes. Update the system and reload - Stonetop will offer to build them from the files you just imported.");
  }
  if (mapRuns.length) {
    progress.phase("Importing poster maps...", `0/${mapRuns.length} maps`);
    progress.step(0);
    await ensureDir(`${CONFIG.ROOT}/assets/maps`);
    for (const [mi, pick] of mapRuns.entries()) {
      // Named rather than counted while the work happens: a 6000px page render plus a WebP
      // encode is seconds of silence, and "3/5 maps" alone reads as a stall.
      progress.step(mi / mapRuns.length, pick.map.name);
      try {
        if (pick.page && pick.page > mapsPdfDoc.numPages) throw new Error(`page ${pick.page} is past the end of a ${mapsPdfDoc.numPages}-page PDF`);
        const img = pick.page ? await uploadMapCanvas(pick.map, await renderMapPdfPage(mapsPdfDoc, pick.page))
          : pick.file ? await uploadMapFile(pick.map, pick.file)
          : await probeMapPath(pick.path);
        if (upsertPosterMapScene) {
          const res = await upsertPosterMapScene(pick.map, img);
          if (res.created) scenesCreated++; else scenesUpdated++;
          pinsPlaced += res.pins;
          log(`map ${pick.map.slug}: scene ${res.created ? "created" : "updated"}, ${res.pins} pins`);
        } else {
          log(`map ${pick.map.slug}: saved to disk; scene skipped (helper unavailable)`);
        }
      } catch (e) { console.error("[Book II Art] map", pick.map.slug, e); failures.push(`map ${pick.map.slug} (${e.message})`); }
      progress.step((mi + 1) / mapRuns.length, `${mi + 1}/${mapRuns.length} maps`);
    }
  }

  // ---- 7c. refresh open journals ------------------------------------------
  // Re-render any world journals we embedded art into that are OPEN right now, so the
  // art appears without an F5. page.update() only live-refreshes a journal that was
  // already open at the instant of the write; one opened afterwards from a pre-art view
  // (or opened mid-run, before its page was written) keeps showing the old, art-less
  // render until a reload - which is exactly what makes a freshly imported journal look
  // empty. Targeted + best-effort: only the entries we touched, so an unrelated journal
  // the GM is editing is left alone. Mirrors module/book2-art/reapply.js.
  const rerenderOpenJournals = (entries) => {
    const ids = new Set();
    for (const e of entries) if (e?.id) ids.add(e.id);
    if (!ids.size) return;
    const apps = [...(foundry.applications?.instances?.values?.() ?? []), ...Object.values(ui.windows ?? {})];
    for (const app of apps) {
      const doc = app?.document ?? app?.object;
      if (doc?.documentName === "JournalEntry" && ids.has(doc.id) && app.rendered) {
        try { app.render(); } catch (_) { /* best-effort refresh */ }
      }
    }
  };
  if (CONFIG.SYNC_WORLD_JOURNALS) rerenderOpenJournals(touchedEntries.keys());

  // Same for the compendia we just wrote to. UNLIKE a world document, a compendium document
  // update does NOT live-refresh the pack browser or a sheet opened from it (Foundry caches the
  // pack), so a GM who runs this import with the Monsters/journal compendium open would see the
  // old, art-less sheets until an F5. Re-render those open views so it "just works" for a
  // non-technical GM. Best-effort. Mirrors module/book2-art/reapply.js (rerenderOpenCompendia).
  const rerenderOpenCompendia = (packs) => {
    const set = new Set((packs ?? []).filter(Boolean));
    if (!set.size) return;
    for (const pack of set) for (const app of pack.apps ?? []) { try { app.render(false); } catch (_) { /* best-effort */ } }
    const ids = new Set([...set].map((p) => p.collection ?? p.metadata?.id).filter(Boolean));
    const apps = [...(foundry.applications?.instances?.values?.() ?? []), ...Object.values(ui.windows ?? {})];
    for (const app of apps) {
      const doc = app?.document ?? app?.object;
      if (doc?.pack && ids.has(doc.pack) && app.rendered) {
        try { app.render(); } catch (_) { /* best-effort */ }
      }
    }
  };
  if (actorsUpdated + besPages + locPages + soPages > 0) rerenderOpenCompendia([besPack, jrnPack]);

  // ---- 8. report ----------------------------------------------------------
  // The art lines are all gated on artRun: on a maps-only run they would every one read zero,
  // which looks like a failed import rather than a run that was never asked to do that work.
  //
  // A run given ONE book is the same thing one level down. artRun is true, so every line printed,
  // and four of them read zero because the books that fill them were never handed over. So a line
  // appears when it has something to say and not otherwise, which is the rule the other ten lines
  // already followed, and the run says up front which books it read and which it did not. A GM
  // importing one page at a time has no other way to tell a short errand from a long one that
  // went wrong.
  const booksRead = [...pdfByBook.keys()].sort((a, b) => a - b).map(bookLabel);
  const booksMissed = booksUsed.filter((b) => !pdfByBook.has(b)).map(bookLabel);
  const andList = (xs) => (xs.length < 2 ? xs[0] ?? "" : `${xs.slice(0, -1).join(", ")} and ${xs.at(-1)}`);
  const report = [
    artRun ? `Read: ${andList(booksRead)}` : null,
    artRun && forceUpdate ? `Force update: existing art re-extracted and replaced` : null,
    artRun ? `Images written: ${okc}/${pending.length}`
      + (skipped ? `, ${skipped} already present` : "")
      + (failures.length ? ` (${failures.length} failed)` : "") : null,
    actorsUpdated + besPages > 0 ? `Monster portraits: ${actorsUpdated} actors, ${besPages} journal pages` : null,
    steadingUpdated ? `Steading portrait: imported from Book I` : null,
    treasureArt ? `Treasure art: ${treasureArt} items will show their illustration when dragged` : null,
    peopleArt ? `People of Stonetop: ${peopleArt} portraits available for residents & neighbors on the steading sheet` : null,
    peopleSquares ? `Square faces: ${peopleSquares} portraits have a close-up for the small round pictures on sheets` : null,
    locPages ? `Location art: ${locPages} journal pages` : null,
    artRun && CONFIG.SYNC_WORLD_JOURNALS && worldJournalPages ? `World journals synced: ${worldJournalPages} pages` : null,
    artRun && CONFIG.SYNC_WORLD_ACTORS && worldActors ? `World actors synced: ${worldActors}` : null,
    mapRuns.length ? `Poster maps: ${scenesCreated} scenes created, ${scenesUpdated} updated` : null,
    pinsPlaced ? `Village pins placed: ${pinsPlaced}` : null,
    soPages ? `Setting Overview maps: ${soPages} pages` : null,
    diagramArt ? `GM playbook diagrams: ${diagramArt} on the GM Toolkit's Core Loop tab` : null,
    // Last, and phrased as the reassurance it is. The count of rows this left alone is deliberately
    // not printed: "545 images not imported" is the exact number that made a five-image run read
    // as a disaster, and what a GM needs to know is that their art is untouched, not how much of it.
    artRun && booksMissed.length ? `Not supplied this time: ${andList(booksMissed)}. That art was left exactly as it is.` : null,
  ].filter(Boolean);
  log("DONE\n" + report.join("\n"));
  if (failures.length) log("FAILURES:\n" + failures.join("\n"));
  await progress.close();
  await foundry.applications.api.DialogV2.wait({
    classes: DLG_CLASSES,
    window: { title: "Import Book Art: Done" },
    position: { width: 480 },
    content: `<p><strong>${artRun ? "Book art imported." : "Poster maps imported."}</strong></p><ul>${report.map((r) => `<li>${esc(r)}</li>`).join("")}</ul>`
      + (failures.length ? `<p style="color:#c66">${failures.length} images failed; see console.</p>` : "")
      + (artRun
        ? `<p style="opacity:.7;font-size:12px">Any journals you had open have been refreshed to show the new art. If a journal still looks empty, reloading shows it. Saved to a durable folder (<code>${esc(CONFIG.ROOT)}</code>), so updates won't wipe it; Stonetop re-applies the art automatically after each update, so re-run only for a new PDF or newly added art.</p>`
        : `<p style="opacity:.7;font-size:12px">No book PDF was supplied, so this run did the maps only and left your imported art exactly as it was. The maps are saved to a durable folder (<code>${esc(CONFIG.ROOT)}</code>), so updates won't wipe them.</p>`),
    buttons: [
      { action: "reload", label: "Reload Now", icon: "fas fa-rotate", callback: () => window.location.reload() },
      { action: "close", label: "Close", default: true },
    ],
    rejectClose: false,
  });
})();
